function home(){const m=nextMethod(),started=totalDone()>0,sys=s.featTab==='systems';
 const features=[
  [sys?'Veja a matriz mudar, linha por linha':'Visual e interativo, não um gabarito',sys?'Na Eliminação de Gauss, cada operação aparece de verdade: trocas de linha, zeros abaixo da diagonal e retrossubstituição. Você acompanha a mesma matriz que o motor calcula.':'Cada método aparece como uma ideia que você vê funcionar. Na Bisseção, o intervalo cai pela metade a cada passo até cercar a raiz.','Você controla o ritmo: avance ou volte um passo de cada vez na simulação.',sys?gaussPreview():bisectionPreview(),'tint-peach'],
  ['Feedback na hora, dica antes do gabarito','Cada etapa tem uma pergunta curta. Se errar, você recebe uma orientação e tenta de novo. A explicação completa aparece quando você acerta.','Estrelas registram a sua melhor tentativa: três para acerto sem dica e sem erro.',questionMock(sys?C.TASKS.gauss[0]:C.TASKS.bisection[0]),'tint-sage'],
  [sys?'Convergência que dá para medir':'Revisão no tempo certo',sys?'No Gauss-Seidel, você vê o resíduo cair a cada iteração e entende quando é seguro parar. O mesmo critério vale para o terminal.':'As questões difíceis vão para o caderno de revisão e voltam depois de 1, 3, 7 e 14 dias, conforme você acerta sem ajuda.',sys?'O critério usa resíduo normalizado e variação relativa, não um número mágico.':'Repetir uma questão melhora as estrelas, mas não multiplica o XP.',sys?seidelPreview():reviewMock(),'tint-sky']];
 const HIDDEN_TITLES=(C.HIDDEN||[]).map(id=>method(id).title);const topics={roots:['Bisseção','Falsa Posição','Ponto Fixo','Newton-Raphson','Secante','Raiz e mudança de sinal','Iteração e critério de parada','Resíduo e erro','Tolerância','Ordem de convergência'],systems:['Eliminação de Gauss','Gauss-Seidel','Pivotamento parcial','Retrossubstituição','Resíduo normalizado','Convergência iterativa','Sistemas sem solução única','Tolerância'],modeling:C.CASES.map(c=>c.title).concat(['Formular, calcular e interpretar','Unidades e domínio físico','Validar a solução']),practice:['Jogos',`${TR?TR.count:0} exercícios de diagnóstico no Treino`,'Modo prova com nota e relatório','Caderno de revisão espaçada','Estrelas por melhor tentativa','XP e níveis','8 conquistas','Backup do progresso']};topics.roots=topics.roots.filter(t=>!HIDDEN_TITLES.includes(t));topics.practice.splice(0,1,'Calculândia, a aventura 3D com 63 fases','Quem Divergiu?, o jogo da turma no telão');topics.practice.splice(5,2,'XP, moedas e níveis','Raiz e Pivô, o casal que torce por você',`${badgeList().length} conquistas`);
 const topicTabs=[['roots','Raízes'],['systems','Sistemas'],['modeling','Modelagem'],['practice','Prática']];
 const topicCta={roots:['Começar com Bisseção','course','bisection'],systems:['Começar com Gauss','course','gauss'],modeling:['Ver as missões','nav','cases'],practice:['Ver os jogos','nav','jogos']}[s.topicsTab];
 return `<section class="hero-band"><div class="wrap hero"><div class="hero-copy"><h1 class="display">Aprenda métodos numéricos resolvendo de verdade</h1><p class="lead">Um laboratório interativo de Modelagem Computacional. Entenda a ideia, veja o método funcionar e pratique até dominar.</p><div class="hero-actions">${btn(started?'Continuar de onde parei':'Começar a aprender','course','primary big',`data-id="${m.id}"`)}${btn('Abrir o terminal','nav','ghost big','data-page="lab"')}</div><div class="hero-badges"><span>${icon('check')}Funciona offline</span><span>${icon('check')}Sem conta</span><span>${icon('check')}Cálculos no navegador</span></div></div><div class="hero-card" id="hero-widget">${heroWidget()}</div></div></section>
 <section class="wrap stats" aria-label="O projeto em números"><div><b>${C.METHODS.length}</b><span>métodos numéricos</span></div><div><b>${visibleIds().length}</b><span>atividades com progresso</span></div><div><b>${TR?TR.count:0}</b><span>exercícios no Treino</span></div><div><b>${VERIFY_COUNT.toLocaleString('pt-BR')}</b><span>verificações automáticas</span></div></section>
 <section class="wrap section meet"><h2 class="display center">Um conceito por vez, sempre com as mãos no problema</h2><div class="seg center-seg" role="group" aria-label="Tema">${[['roots','Raízes de equações'],['systems','Sistemas lineares']].map(([id,t])=>`<button type="button" data-act="feat" data-id="${id}" class="${s.featTab===id?'active':''}" aria-pressed="${s.featTab===id}">${t}</button>`).join('')}</div><div class="feature-rows">${features.map(([t,a,b2,media,tint],i)=>`<div class="feature ${i%2?'flip':''}"><div class="feature-text"><h3>${t}</h3><p>${a}</p><p>${b2}</p></div><div class="feature-media ${tint}"><div class="media-card">${media}</div></div></div>`).join('')}</div></section>
 <section class="band-white"><div class="wrap section"><h2 class="display center">Eficaz e transparente</h2><div class="trust-grid"><article class="trust-card"><div class="trust-visual tint-sand"><code>x³ − 4 = 0</code><small>aresta do reservatório ≈ ${short(C.CASES[0].tasks[2].value)} m</small></div><h3>Missões de modelagem</h3><p>${cap(words(C.CASES.length))} problemas aplicados, cada um em três partes: formular a equação, calcular e interpretar o resultado.</p></article><article class="trust-card"><div class="trust-visual dark">${teaserScreen()}</div><h3>Terminal com verificação</h3><p>Digite uma equação ou um sistema e veja a comparação entre métodos, a tabela de iterações e a substituição da resposta.</p></article><article class="trust-card"><div class="trust-visual tint-lilac"><ul class="dash-list compact"><li>Encontrar todas as raízes</li><li>Um método sempre mais rápido</li></ul></div><h3>Limites declarados</h3><p>O Numera diz o que não garante. Resíduo pequeno não significa erro pequeno, e ausência de raiz encontrada não prova que ela não existe.</p></article></div></div></section>
 <section class="wrap section topics"><h2 class="display center">Do primeiro palpite ao domínio</h2><div class="seg center-seg" role="group" aria-label="Área">${topicTabs.map(([id,t])=>`<button type="button" data-act="topics" data-id="${id}" class="${s.topicsTab===id?'active':''}" aria-pressed="${s.topicsTab===id}">${t}</button>`).join('')}</div><div class="topics-card"><div><span class="eyebrow">Tópicos cobertos</span><ul class="topic-list">${topics[s.topicsTab].map(t=>`<li>${icon('check')}${safe(t)}</li>`).join('')}</ul></div><div class="topics-cta">${s.topicsTab==='roots'||s.topicsTab==='systems'?`<div class="topic-arts">${(s.topicsTab==='roots'?ROOTS():SYSTEMS()).map(m=>m.id).map(id=>`<button type="button" class="topic-art tone-${id}" data-act="course" data-id="${id}" aria-label="${method(id).title}">${art(id)}<span>${method(id).title}</span></button>`).join('')}</div>`:''}${btn(topicCta[0]+' '+icon('arrow'),topicCta[1],'primary',topicCta[1]==='course'?`data-id="${topicCta[2]}"`:`data-page="${topicCta[2]}"`)}</div></div></section>
 <section class="wrap section"><div class="feature"><div class="feature-text"><h3>No seu ritmo, até sem internet</h3><p>Não precisa de conta nem de servidor. O progresso fica salvo no seu navegador, e você leva tudo para outro computador com um backup em JSON.</p><p>Uma meta diária de três atividades e a sequência de dias ajudam a manter o hábito.</p></div><div class="feature-media tint-sand"><div class="media-card">${calendarMock()}</div></div></div><div class="feature flip"><div class="feature-text"><h3>Feito com método</h3><p>Um interpretador próprio lê as equações sem usar <code>eval()</code>. Os ${words(C.METHODS.length)} métodos passam por uma suíte de ${VERIFY_COUNT.toLocaleString('pt-BR')} verificações automáticas.</p><div class="refs"><span>Driscoll &amp; Braun</span><span>Netlib Templates</span><span>Modelagem Computacional</span></div></div><div class="feature-media tint-peach"><div class="media-card"><span class="eyebrow">Newton-Raphson em pseudocódigo</span><pre class="pseudocode">${safe(C.DEEP.newton.pseudo)}</pre></div></div></div></section>
 <section class="cta-band"><div class="wrap cta-inner"><h2 class="display">A próxima raiz começa com um palpite</h2>${btn((started?'Continuar':'Começar agora')+' '+icon('arrow'),'course','light big',`data-id="${m.id}"`)}</div></section>`;}

/* ---------- Catálogo de trilhas ---------- */
function courseCard(m){const n=doneCount(m.id);return `<button type="button" class="course-card" data-act="course" data-id="${m.id}"><span class="course-art tone-${m.id}">${art(m.id)}</span><span class="course-body"><b>${m.title}</b><small>3 níveis · 12 etapas</small>${n?bar(n,12,'Progresso em '+m.title):''}</span></button>`;}
function worldCard(m,i){const w=world(m.id),n=doneCount(m.id),open=worldOpen(m.id),pr=prevWorld(m.id),lv=[0,1,2].map(l=>[0,1,2,3].filter(j=>p.completed[`c:${m.id}:${l*4+j}`]).length),done=n===12;
 return `<li class="world ${open?'':'locked'} ${done?'done':''} side-${i%2?'r':'l'}"><button type="button" class="world-card" data-act="course" data-id="${m.id}" aria-label="Mundo ${i+1}: ${m.title}. ${w.tier?'Dificuldade '+w.tier+', ':''}${w.stars} de 5. ${n} de 12 etapas.${open?'':' Desafios bloqueados.'}">
  <span class="world-num" aria-hidden="true">${done?icon('check'):open?i+1:icon('lock')}</span>
  <span class="world-art tone-${m.id}" aria-hidden="true">${art(m.id)}</span>
  <span class="world-body"><span class="world-top"><small>Mundo ${i+1}</small>${tierTag(m.id)}${diffStars(w.stars)}</span><b>${m.title}</b>
  <span class="world-levels" aria-hidden="true">${lv.map((k,l)=>`<span class="wl ${k===4?'full':k?'part':''}"><i style="--k:${k}"></i><small>${['Fácil','Médio','Difícil'][l]}</small></span>`).join('')}</span>
  <span class="world-why">${open?safe(w.why):`Conclua o Nível 1 de ${safe(pr?pr.title:'')} para abrir os desafios. A leitura e a simulação já estão liberadas.`}</span></span></button></li>`;}
function academy(){const done=C.METHODS.filter(m=>doneCount(m.id)===12).length;return `<div class="wrap page-body">${heading('Trilhas','A jornada dos métodos','Do mais fácil ao mais difícil: cada mundo é um método, com três níveis (Fácil, Médio e Difícil). Termine o Nível 1 de um mundo para abrir o próximo.',`<div class="head-stat"><b>${courseDone()}</b><span>de ${C.METHODS.length*12} etapas</span></div>`)}
 <div class="journey-bar card"><div class="jb-stats"><span>${coinChip()}<small>moedas</small></span><span><b>${done}/${C.METHODS.length}</b><small>mundos completos</small></span><span><b>${p.best||0}</b><small>melhor sequência</small></span></div><button type="button" class="switch ${p.free?'on':''}" data-act="free-toggle" role="switch" aria-checked="${!!p.free}"><span class="switch-track" aria-hidden="true"><i></i></span><span><b>Modo livre</b><small>${p.free?'Todos os mundos abertos (para professores e revisão).':'Abre todos os mundos de uma vez, sem seguir a ordem.'}</small></span></button></div>
 <ol class="journey" aria-label="Mundos, do mais fácil ao mais difícil">${C.METHODS.map(worldCard).join('')}</ol>
 <details class="card journey-why"><summary>Por que essa ordem?</summary><p>${safe(C.JOURNEY_NOTE||'')}</p><ol>${C.METHODS.map(m=>`<li><b>${m.title}</b> ${tierTag(m.id)} ${diffStars(world(m.id).stars,'small')} <span>${safe(world(m.id).why)}</span></li>`).join('')}</ol><p class="fine">Fontes: Rachmatin e Sujana (2022), estudo com 68 estudantes sobre raízes de equações não lineares; Díaz Quezada (2020), dificuldades de estudantes de engenharia com derivadas.</p></details>
 <section class="catalog"><h2>Aplicação e prática</h2><div class="course-grid"><button type="button" class="course-card" data-act="nav" data-page="cases"><span class="course-art tint-sand"><span class="art-glyph">◈</span></span><span class="course-body"><b>Missões de modelagem</b><small>${C.CASES.length} missões · ${C.CASES.length*3} etapas</small></span></button><button type="button" class="course-card" data-act="nav" data-page="jogos"><span class="course-art tint-lilac"><span class="art-glyph">▲</span></span><span class="course-body"><b>Jogos</b><small>Calculândia em 3D e o Quem Divergiu? para a turma</small></span></button><button type="button" class="course-card" data-act="nav" data-page="treino"><span class="course-art tint-sage"><span class="art-glyph">⚑</span></span><span class="course-body"><b>Treino e modo prova</b><small>${TR?TR.count:0} exercícios de diagnóstico</small></span></button><button type="button" class="course-card" data-act="nav" data-page="review"><span class="course-art tint-sky"><span class="art-glyph">↻</span></span><span class="course-body"><b>Caderno de revisão</b><small>${Object.keys(p.review).filter(id=>!hiddenId(id)).length} questões guardadas</small></span></button></div></section>
 <details class="card glossary"><summary>Fundamentos que conectam os ${words(C.METHODS.length)} métodos</summary><div class="glossary-grid">${C.GLOSSARY.map(([t,d])=>`<div><h3>${t}</h3><p>${d}</p></div>`).join('')}</div></details></div>`;}

/* ---------- Página do curso: níveis em caminho ---------- */
const LEVEL_NAMES=['Primeiros passos','Na prática','Domínio'],LEVEL_TIERS=['Fácil','Médio','Difícil'];
function pathNodes(id){return [{key:'intro',kind:'intro',label:'Entenda o método',lvl:0},{key:'sim',kind:'sim',label:'Veja o método em ação',lvl:0},...C.TASKS[id].map((t,i)=>({key:'t'+i,kind:'task',i,label:C.LEVELS[i],lvl:i<4?0:i<8?1:2,check:i===7||i===11}))];}
function nodeDone(id,n){return n.kind==='task'?!!p.completed[`c:${id}:${n.i}`]:!!visited[`${id}:${n.kind}`]||doneCount(id)>0;}
function currentNode(id){const nodes=pathNodes(id);if(!doneCount(id)){if(!nodeDone(id,nodes[0]))return 'intro';if(!nodeDone(id,nodes[1]))return 'sim';}return doneCount(id)===12?null:'t'+nextQ(id);}
function nodeLocked(id,n){return n.kind==='task'&&(!worldOpen(id)||n.i>nextQ(id)&&!p.completed[`c:${id}:${n.i}`]);}
function courseOverview(){const m=method(s.method),d=C.DEEP[m.id],nodes=pathNodes(m.id),cur=currentNode(m.id),sel=s.pathSel||cur,n=doneCount(m.id),mission=C.CASES.find(c=>c.method===m.id)||C.CASES[0];const offs=[0,56,84,56,0,-56,-84,-56];let k=0;
 const lvlHtml=[0,1,2].map(l=>`<div class="level"><div class="level-pill lv-${l}"><span>Nível ${l+1} · ${LEVEL_TIERS[l]}</span><b>${LEVEL_NAMES[l]}</b></div><div class="level-nodes">${nodes.filter(nd=>nd.lvl===l).map(nd=>{const off=offs[(k++)%offs.length],done=nodeDone(m.id,nd),locked=nodeLocked(m.id,nd),isCur=nd.key===cur,isSel=nd.key===sel;const pop=isSel?`<div class="node-pop" role="group" aria-label="${safe(nd.label)}"><b>${safe(nd.label)}</b><small>${nd.kind==='intro'?'Leitura guiada em 7 telas, com aulas em vídeo':nd.kind==='sim'?'Simulação passo a passo':nd.check?'Etapa de verificação do nível':`Etapa ${nd.i+1} de 12`}</small>${locked?`<span class="pop-locked">${worldOpen(m.id)?'Conclua a etapa anterior para liberar':`Conclua o Nível 1 de ${safe(prevWorld(m.id).title)} para abrir este mundo`}</span>`:btn(done?'Revisar':'Começar','start-node','blue',`data-id="${nd.key}"`)}</div>`:'';return `<div class="node-row" style="--off:${off}px"><button type="button" class="pnode ${done?'done':''} ${isCur?'current':''} ${locked?'locked':''} ${nd.check?'check':''} ${isSel?'selected':''}" data-act="node" data-id="${nd.key}" aria-label="${safe(nd.label)}${done?' (concluída)':locked?' (bloqueada)':''}"><span class="pnode-face">${locked?icon('lock'):done?icon('check'):nd.kind==='intro'?icon('book'):nd.kind==='sim'?icon('play'):nd.check?icon('flag'):nd.i+1}</span></button><span class="pnode-label ${locked?'muted':''}">${safe(nd.label)}${nd.kind==='task'&&p.completed[`c:${m.id}:${nd.i}`]?stars(p.completed[`c:${m.id}:${nd.i}`].stars):''}</span>${pop}</div>`;}).join('')}</div></div>`).join('');
 return `<div class="wrap page-body"><div class="course-layout"><aside class="course-side"><div class="side-card">${btn(icon('back')+' Trilhas','nav','back','data-page="academy"')}<span class="side-art tone-${m.id}">${art(m.id,'large')}</span><span class="eyebrow">Mundo ${worldIdx(m.id)+1} de ${C.METHODS.length} · ${safe(m.category)}</span><h1 class="display">${m.title}</h1><div class="world-diff">${tierTag(m.id)}${diffStars(world(m.id).stars)}</div>${worldOpen(m.id)?'':`<div class="notice lock-note"><span>${icon('lock')} Os desafios deste mundo abrem quando você concluir o Nível 1 de <b>${safe(prevWorld(m.id).title)}</b>. A leitura e a simulação já estão liberadas.</span></div>`}<p>${m.short} ${d.goal}</p><div class="side-stats"><span>${icon('academy')} 3 níveis</span><span>${icon('check')} ${n}/12 etapas</span></div>${bar(n,12,'Progresso na trilha')}${cur?btn((n?'Continuar':'Começar')+' '+icon('arrow'),'start-node','primary wide',`data-id="${cur}"`):btn('Revisar a ideia','start-node','ghost wide','data-id="intro"')}</div><div class="side-card plain"><h2>Sobre esta trilha</h2><p>${m.concept}</p><h3>Tópicos</h3><ul class="topic-list small">${d.steps.map(t=>`<li>${icon('check')}${safe(t)}</li>`).join('')}</ul><h3>Missão relacionada</h3><button type="button" class="link-row" data-act="case" data-id="${mission.id}"><span>${mission.icon}</span>${mission.title}${icon('arrow')}</button></div></aside><section class="path" aria-label="Caminho da trilha">${lvlHtml}</section></div>${C.VIDEOS&&C.VIDEOS[m.id]?`<section class="card course-videos" aria-labelledby="vid-title"><span class="eyebrow">Para estudar também</span><h2 id="vid-title" class="display small">Aulas em vídeo sobre ${m.title}</h2>${videoList(m.id)}</section>`:''}</div>`;}

/* ---------- Aulas em vídeo (v10) ----------
   Vídeos de terceiros no YouTube. "Assistir aqui" só aparece quando a página está num endereço http(s)
   (aberta do disco, ou dentro de uma página que proíbe players externos, fica só o link) e carrega o player
   do youtube-nocookie apenas depois do clique: nada é baixado nem guardado pelo Numera. */
const NO_EMBED=(()=>{try{return !/^https?:$/.test(location.protocol)||!!document.querySelector('meta[name="numera-no-embed"]');}catch(_){return true;}})();
function videoList(id,where){const vs=(C.VIDEOS&&C.VIDEOS[id])||[];if(!vs.length)return '';
 return `<div class="videos ${where||''}">${vs.map((v,k)=>{const key=`${id}:${k}`,open=s.videoOpen===key;return `<article class="video-card"><div class="video-tags"><span class="video-chip lang-${v.lang}">${v.lang==='pt'?'Português':'Inglês'}</span><span class="video-chip">${safe(v.kind)}</span></div><h3>${safe(v.title)}</h3><p class="video-channel">${safe(v.channel)}</p><p class="fine">${safe(v.note)}</p>${open?`<div class="video-frame"><iframe src="https://www.youtube-nocookie.com/embed/${encodeURIComponent(v.id)}?rel=0" title="${safe(v.title)}" allow="encrypted-media; picture-in-picture; fullscreen" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div>`:''}<div class="row-actions">${NO_EMBED?'':btn(open?'Fechar o vídeo':icon('play')+' Assistir aqui','video-toggle',open?'ghost':'blue',`data-id="${key}" aria-expanded="${open}"`)}<a class="btn text" href="https://www.youtube.com/watch?v=${encodeURIComponent(v.id)}" target="_blank" rel="noopener noreferrer">Abrir no YouTube ↗<span class="sr-only"> (abre em nova aba)</span></a></div></article>`;}).join('')}</div>
 <p class="fine video-note">Vídeos de canais de terceiros, hospedados no YouTube: precisam de internet e podem sair do ar ou mudar. O Numera só aponta para eles; não baixa nem guarda os vídeos.</p>`;}

/* ---------- Lição em tela cheia ---------- */
function introScreens(){const m=method(s.method),d=C.DEEP[m.id];return [
 {eyebrow:'A ideia central',title:m.short,body:`<p class="lead">${m.concept}</p><div class="formula big">${safe(m.formula)}</div>`},
 {eyebrow:'Antes de começar',title:'Quais condições precisam valer?',body:`<p class="lead">${d.requires}</p><div class="callout"><strong>Dica</strong><p>${safe(m.tip)}</p></div>`},
 {eyebrow:'Como executar',title:'O procedimento, passo a passo',body:`<ol class="numbered">${d.steps.map(t=>`<li>${safe(t)}</li>`).join('')}</ol>`},
 {eyebrow:'Critério de parada',title:'Quando parar?',body:`<p class="lead">${d.stop}</p>`},
 {eyebrow:'Olhar crítico',title:'O que pode dar errado?',body:`<p class="lead">${d.trap}</p><div class="example-box"><span class="eyebrow">Exemplo</span><p>${safe(m.example)}</p></div>`},
 {eyebrow:'Do raciocínio ao algoritmo',title:'Em pseudocódigo',body:`<pre class="pseudocode">${safe(d.pseudo)}</pre>`},
 {eyebrow:'Aulas em vídeo',title:'Quer ouvir alguém explicando?',body:`<p class="lead">Escolhemos aulas de ${m.title} de professores de Cálculo Numérico. Assista e depois volte para a simulação: ver o método rodando passo a passo ajuda a fixar o que a aula explicou.</p>${videoList(m.id,'in-player')}`}];}
function playerTop(segs,label,closeAct,closeAttrs){return `<div class="player-top"><button type="button" class="icon-btn" data-act="${closeAct}" ${closeAttrs} aria-label="Fechar e voltar">${icon('close')}</button><div class="player-progress" role="img" aria-label="${safe(label)}">${segs.map(c=>`<i class="${c}"></i>`).join('')}</div><span class="player-meta">${comboPips()}${coinChip()}<span class="xp-meta">✦ ${p.xp}</span></span></div>`;}
function levelSegs(){const l=s.q<4?0:s.q<8?1:2;return [0,1,2,3].map(j=>{const i=l*4+j;return p.completed[`c:${s.method}:${i}`]?'done':i===s.q?'current':'';});}
function introPlayer(){const sc=introScreens(),i=Math.min(s.introStep,sc.length-1),cur=sc[i],last=i===sc.length-1;return `<div class="player">${playerTop(sc.map((_,j)=>j<i?'done':j===i?'current':''),`Tela ${i+1} de ${sc.length}`,'course-tab','data-id="learn"')}<div class="player-body"><div class="player-col"><span class="eyebrow">${cur.eyebrow}</span><h1 class="display">${cur.title}</h1>${cur.body}</div></div><div class="player-bar"><div class="player-bar-inner"><span class="bar-count">${i+1} de ${sc.length}</span><div class="answer-actions">${i?btn('Voltar','intro-prev','ghost'):''}${btn(last?'Ver o método em ação '+icon('arrow'):'Continuar','intro-next','primary')}</div></div></div></div>`;}
function simulationResult(){const m=s.method,d=C.DEEP[m],o={tolerance:1e-8,maxIterations:80};if(d.system){const {A,b}=M.parseSystem(d.system);return m==='gauss'?M.gauss(A,b,o):M.seidel(A,b,A.map(()=>0),o);}const fn=M.parseFunction(d.example);return m==='bisection'?M.bisection(fn,d.a,d.b,o):m==='falseposition'?M.falsePosition(fn,d.a,d.b,o):m==='fixedpoint'?M.fixedPoint(M.parseFunction(d.g),d.x0,o):m==='newton'?M.newton(fn,d.x0,o):M.secant(fn,d.x0,d.x1,o);}
function matrix(mat){return `<div class="matrix-wrap"><table class="matrix" aria-label="Matriz aumentada"><tbody>${mat.map(r=>`<tr>${r.map((x,i)=>`<td class="${i===r.length-1?'rhs':''}">${num(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function simulation(){const r=simulationResult(),d=C.DEEP[s.method],i=Math.min(s.sim,r.iterations.length-1),row=r.iterations[i];return `<div class="player">${playerTop(r.iterations.map((_,j)=>j<i?'done':j===i?'current':''),`Registro ${i+1} de ${r.iterations.length}`,'course-tab','data-id="learn"')}<div class="player-body"><div class="player-col wide"><span class="eyebrow">Execução real · você controla o ritmo</span><h1 class="display">${d.system?'Acompanhe o sistema':'Siga as aproximações'}</h1><div class="sim-stage">${d.system?`<pre class="formula">${safe(d.system)}</pre>${row.matrix?matrix(row.matrix):`<div class="vector">${row.x.map((v,k)=>`<span>x${k+1}<b>${num(v)}</b></span>`).join('')}</div>`}`:s.method==='fixedpoint'?cobweb(M.parseFunction(d.g),r,row):graph(M.parseFunction(d.example),r,d,row)}</div><div class="step-explain"><h3>${row.i===0?'Condições iniciais':`Registro ${i+1} de ${r.iterations.length}`}</h3><p>${safe(row.detail)}</p>${typeof row.x==='number'?`<div class="formula">x ≈ ${num(row.x)} · ${s.method==='fixedpoint'?'|x − g(x)|':'|f(x)|'} = ${num(Math.abs(row.fx))}</div>`:row.residual!==undefined?`<div class="formula">resíduo máximo = ${num(row.residual)}</div>`:''}<p class="fine">${s.method==='falseposition'?`A faixa destacada é o intervalo [a, b] deste passo e a reta liga (a, f(a)) a (b, f(b)). O novo ponto é onde essa corda cruza o eixo.${row.kept?` Depois do corte, a ponta ${row.kept==='b'?'b':'a'} é mantida.`:''}`:s.method==='fixedpoint'?`Diagrama em teia: a curva é y = g(x) e a diagonal é y = x. Cada degrau sobe até g e volta à diagonal, que transforma g(xₖ) no próximo xₖ₊₁ (aqui g(x) = ${safe(d.g)}).`:s.method==='bisection'?'A faixa destacada é o intervalo usado neste passo. Metade da sua largura limita o erro do ponto médio, sob as hipóteses do método.':s.method==='newton'?'A reta tracejada é a tangente aproximada do passo selecionado. A derivada aqui é numérica.':s.method==='secant'?'A reta tracejada liga os dois pontos anteriores usados neste passo.':'Confira a atualização de cada linha e a ordem em que os valores são utilizados.'}</p></div></div></div><div class="player-bar"><div class="player-bar-inner"><div class="sim-controls">${btn('←','sim-prev','ghost round',`aria-label="Passo anterior" ${i===0?'disabled':''}`)}<input aria-label="Passo da simulação" id="sim-range" type="range" min="0" max="${r.iterations.length-1}" value="${i}">${btn('→','sim-next','ghost round',`aria-label="Próximo passo" ${i===r.iterations.length-1?'disabled':''}`)}</div><div class="answer-actions">${btn((worldOpen(s.method)?'Começar a praticar ':'Voltar à trilha ')+icon('arrow'),'sim-done','primary')}</div></div></div></div>`;}
function practice(){const id=`c:${s.method}:${s.q}`,task=C.TASKS[s.method][s.q],l=s.q<4?0:s.q<8?1:2;return `<div class="player">${playerTop(levelSegs(),`Nível ${l+1}: etapa ${s.q%4+1} de 4`,'course-tab','data-id="learn"')}<div class="player-body"><div class="player-col"><span class="eyebrow">Nível ${l+1} · ${C.LEVELS[s.q]}</span><p class="coach">${safe(C.COACH[s.method][s.q]||'Agora vá além da fórmula: pense nas condições, no erro e em como validar o resultado.')}</p>${question(task,id,'next-course')}</div></div></div>`;}
function course(){if(s.tab==='intro')return introPlayer();if(s.tab==='simulate')return simulation();if(s.tab==='practice')return practice();return courseOverview();}
function taskFor(id){const a=id.split(':');if(a[0]==='c')return C.TASKS[a[1]][+a[2]];if(a[0]==='a')return C.ARENA[+a[1]];return C.CASES.find(c=>c.id===a[1]).tasks[+a[2]];}
function currentId(){return s.page==='review'?s.reviewId:s.page==='case'?`p:${s.caseId}:${s.caseQ}`:`c:${s.method}:${s.q}`;}
function question(task,id,nextAction){const completed=p.completed[id];let opts=task.options?.map((v,i)=>({v,i}));if(opts){const shift=[...id].reduce((n,c)=>n+c.charCodeAt(0),0)%opts.length;opts=opts.slice(shift).concat(opts.slice(0,shift));}const reward=id.startsWith('p:')?'+40 XP':id.startsWith('a:')?'+30 XP':'+20 XP',fb=s.feedback;
 return `<form id="quiz-form" class="quiz" data-id="${id}"><div class="quiz-meta">${tag(task.type==='choice'?'Raciocínio':'Aplicação numérica')}${completed?tag('✓ Concluída '+stars(completed.stars),'green'):tag(reward,'xp')}</div><h2 class="quiz-q">${safe(task.q.replace('DESAFIO FINAL: ',''))}</h2>${opts?`<div class="choices" role="group" aria-label="Alternativas">${opts.map((o,j)=>`<button type="button" class="choice ${s.selected===o.i?'selected':''}" data-act="select" data-index="${o.i}" aria-pressed="${s.selected===o.i}"><span class="choice-key">${String.fromCharCode(65+j)}</span><span>${safe(o.v)}</span></button>`).join('')}</div>`:`<label class="answer-label" for="answer">Seu resultado</label><div class="answer-line"><input id="answer" type="text" inputmode="decimal" autocomplete="off" placeholder="Ex.: 1,416667 ou 17/12" value="${safe(s.answer)}"><span>Use ao menos 4 casas decimais quando necessário. Frações como 17/12 também valem.</span></div>`}
 ${s.hint?`<div class="hint-box"><b>Dica.</b> ${safe(task.hint||task.wrong||'Identifique os dados, escolha a fórmula e calcule cada termo antes de substituir.')}</div>`:''}
 <div class="player-bar ${fb?(fb.ok?'is-ok':'is-bad'):''}"><div class="player-bar-inner">${fb?`<div class="sheet-msg" role="status"><b>${fb.ok?'Correto!':'Ainda não.'}</b><span>${safe(fb.message.replace(/^Correto\.\s*/,''))}</span></div>`:`<span class="bar-count">${completed?'Refazer melhora as estrelas; o XP é recebido uma vez.':'Sem cronômetro. Pedir dica também faz parte.'}</span>`}<div class="answer-actions">${fb?.ok?btn('Continuar '+icon('arrow'),nextAction,'primary'):`${btn(s.hint?'Dica aberta':'Dica','hint','ghost',s.hint?'disabled':'')}<button class="btn primary" type="submit" id="check-btn">${fb?'Tentar de novo':'Conferir'}</button>`}</div></div></div></form>`;}

/* ---------- Missões ---------- */
function cases(){return `<div class="wrap page-body">${heading('Missões','Missões de modelagem','Problemas idealizados em três partes: formular a equação, calcular e interpretar o resultado.')}<div class="course-grid cases">${C.CASES.map((c,i)=>{const n=c.tasks.filter((_,j)=>p.completed[`p:${c.id}:${j}`]).length;return `<button type="button" class="course-card mission" data-act="case" data-id="${c.id}"><span class="course-art tint-${i}"><span class="art-glyph">${c.icon}</span><code>${safe(c.expression.split('\n')[0])}</code></span><span class="course-body"><small class="eyebrow">${safe(c.area)}</small><b>${c.title}</b><span class="mission-story">${c.story}</span><small>${method(c.method).title} · ${n}/3 etapas</small><span class="mission-diff">${tierTag(c.method)}${diffStars(world(c.method).stars,'small')}</span>${n?bar(n,3,'Progresso da missão'):''}</span></button>`;}).join('')}</div></div>`;}
function casePage(){const c=C.CASES.find(c=>c.id===s.caseId),i=C.CASES.indexOf(c);return `<div class="player">${playerTop([0,1,2].map(k=>p.completed[`p:${c.id}:${k}`]?'done':k===s.caseQ?'current':''),`Etapa ${s.caseQ+1} de 3`,'nav','data-page="cases"')}<div class="player-body"><div class="player-col"><span class="eyebrow">${safe(c.area)} · ${['Formular','Calcular','Interpretar'][s.caseQ]}</span><h1 class="display small">${c.title}</h1><div class="case-story tint-${i}"><p>${c.story}</p><details><summary>Ver a formulação do modelo</summary><p>${c.model}</p>${btn('Investigar no terminal ↗','case-terminal','text')}</details></div>${question(c.tasks[s.caseQ],`p:${c.id}:${s.caseQ}`,'next-case')}${s.caseQ===2&&s.feedback?.ok?`<div class="callout"><strong>Interpretação do modelo</strong><p>${c.interpret}</p></div>`:''}</div></div></div>`;}


/* ---------- Jogos (v12): no lugar da Arena ----------
   Calculândia (aventura 3D, em jogos/calculandia) e Quem Divergiu? (jogo de sala, em jogos/quem-divergiu).
   Os dois salvam no próprio navegador; aqui só lemos o resumo, com cada campo conferido. */
const readJSON=key=>{try{const raw=localStorage.getItem(key);if(!raw)return null;const d=JSON.parse(raw);return d&&typeof d==='object'?d:null;}catch(_){return null;}};
function calcSummary(){const d=readJSON('calculandia-save-v1');if(!d)return null;const ph=d.phases&&typeof d.phases==='object'?d.phases:{};let stars=0,wins=0;for(const [k,v] of Object.entries(ph)){if(!v||typeof v!=='object')continue;if(Number(v.wins)>0)wins++;if(/-[FMD]$/.test(k))stars+=Math.max(0,Math.min(3,Math.floor(Number(v.stars)||0)));}const roots=d.roots&&typeof d.roots==='object'?Object.keys(d.roots).length:0;return {stars:Math.min(189,stars),roots:Math.min(40,roots),wins:Math.min(69,wins)};}
function qdSummary(){const d=readJSON('numera-quem-divergiu-v1'),st=d&&d.stats&&typeof d.stats==='object'?d.stats:{},n=v=>Math.max(0,Math.min(1e6,Math.floor(Number(v)||0)));return {games:n(st.games),rounds:n(st.rounds)};}
function jogos(){const cs=calcSummary(),qd=qdSummary();
 const card=(o)=>`<article class="game-card card ${o.cls}" aria-labelledby="${o.id}-t"><a class="game-cover" href="${o.href}" tabindex="-1" aria-hidden="true"><img src="${o.img}" alt="" width="1200" height="675" loading="lazy" decoding="async"></a><div class="game-body"><span class="eyebrow">${o.eyebrow}</span><h2 class="display" id="${o.id}-t">${o.title}</h2><p>${o.text}</p><ul class="game-facts">${o.facts.map(([b,t])=>`<li><b>${b}</b><span>${t}</span></li>`).join('')}</ul><p class="game-progress">${o.progress}</p><div class="row-actions"><a class="btn primary" href="${o.href}">${o.cta} ${icon('arrow')}</a></div><p class="fine">${o.note}</p></div></article>`;
 return `<div class="wrap page-body">${heading('Jogos','Aprenda jogando','Os mesmos métodos das trilhas em dois jogos: uma aventura para jogar sozinho e um jogo de sala para a turma inteira, no telão.')}<div class="games">
 ${card({id:'calc',cls:'game-calc',href:'jogos/calculandia/index.html',img:'jogos/capas/calculandia.webp',eyebrow:'Aventura 3D · para jogar sozinho',title:'Calculândia — Caçadores de Raízes',text:'Explore uma ilha em 3D, converse com os bichos guias e resolva fases táticas: arraste o intervalo da Bisseção, mire a tangente do Newton, prepare a eliminação de uma matriz. Cada região termina num chefão, e a Usina junta tudo.',facts:[['63','fases'],['21','métodos'],['5','chefões e a Usina']],progress:cs?`⭐ ${cs.stars} de 189 estrelas · ${cs.wins} ${cs.wins===1?'fase vencida':'fases vencidas'} · ${cs.roots} de 40 Raízes Fugitivas`:'Ainda não começou. O progresso fica salvo neste navegador.',cta:'Jogar a Calculândia',note:'Teclado e mouse, ou toque. Precisa de WebGL; num computador mais fraco, use Menu → Opções → Qualidade leve.'})}
 ${card({id:'qd',cls:'game-qd',href:'jogos/quem-divergiu/index.html',img:'jogos/capas/quem-divergiu.webp',eyebrow:'Jogo de sala · para o telão',title:'Quem Divergiu?',text:'A professora projeta uma pergunta da matéria com resposta numérica. Cada aluno faz um palpite em segredo, a turma vota em quem deve ter divergido, e a reta numérica revela a resposta com as faixas de tolerância. Quem chega mais perto converge; quem erra feio leva o carimbo.',facts:[['2 a 12','jogadores ou times'],['3','faixas de tolerância'],['0','instalação']],progress:qd.games?`${qd.games} ${qd.games===1?'partida jogada':'partidas jogadas'} neste navegador · ${qd.rounds} rodadas`:'Nenhuma partida ainda. Dá para jogar com palpites no papel ou passando o aparelho.',cta:'Abrir no telão',note:'Funciona offline num computador só, ligado ao projetor. As respostas são calculadas pelo motor do Numera, com o passo a passo para a professora explicar.'})}
 </div><section class="card games-howto" aria-labelledby="howto-t"><h2 id="howto-t">Como jogar o Quem Divergiu? em sala</h2><ol><li><b>Monte a turma.</b> Até 12 nomes, ou times (Fileira 1, Fileira 2…). Escolha os métodos que a turma já viu e o número de rodadas.</li><li><b>Palpite em segredo.</b> No modo telão, cada um escreve o número no caderno; no modo passa o aparelho, cada um digita escondido.</li><li><b>Vote em quem divergiu.</b> Cada jogador aponta quem ele acha que errou mais. Os votos aparecem juntos.</li><li><b>Revele.</b> A resposta cai na reta numérica com as faixas de 1%, 5% e 20%. Pontos por proximidade, por voto certeiro e para quem foi votado sem ter errado mais.</li></ol></section></div>`;}

/* ---------- Revisão e progresso ---------- */
function review(){const all=Object.keys(p.review),ready=due(),trs=TR?TR.reviewSection():'';if(s.reviewId&&P.ids.has(s.reviewId))return `<div class="player">${playerTop(['current'],'Revisão ativa','review-close','')}<div class="player-body"><div class="player-col"><span class="eyebrow">Revisão ativa</span><p class="coach">Tente lembrar o procedimento antes de abrir a dica. Um acerto sem ajuda adia a próxima revisão.</p>${question(taskFor(s.reviewId),s.reviewId,'review-next')}</div></div></div>`;
 return `<div class="wrap page-body">${heading('Revisão','Erros que viram aprendizado','As questões com dificuldade e os diagnósticos errados do Treino ficam aqui. Depois de revisões sem ajuda, o intervalo cresce de 1 para 3, 7 e 14 dias.')}${trs}${all.length?`<div class="stat-row"><div class="stat card"><span>Para revisar hoje</span><b>${ready.length}</b></div><div class="stat card"><span>No seu caderno</span><b>${all.length}</b></div><div class="stat card action"><span>Seu próximo passo</span>${btn('Revisar uma questão '+icon('arrow'),'review-start','primary',`data-id="${ready[0]||all[0]}"`)}</div></div><div class="review-list">${all.map(id=>`<article class="card review-row"><span class="review-marker ${p.review[id].due<=P.day()?'due':''}" aria-hidden="true">${p.review[id].due<=P.day()?'↻':'✓'}</span><div><span class="eyebrow">${p.review[id].due<=P.day()?'Revisão disponível':'Próxima revisão: '+p.review[id].due.split('-').reverse().join('/')}</span><h3>${safe(taskFor(id).q.replace('DESAFIO FINAL: ',''))}</h3></div>${btn('Praticar','review-start','ghost',`data-id="${id}"`)}</article>`).join('')}</div>`:trs?'':`<section class="card empty-state">${icon('review')}<h2 class="display">Seu caderno ainda está em branco</h2><p>Quando uma questão exigir outra tentativa ou uma dica, ela aparece aqui.</p>${btn('Começar uma trilha','nav','primary','data-page="academy"')}</section>`}</div>`;}
const badgeList=()=>[
['Primeira descoberta','Conclua uma atividade.',totalDone()>=1,'✦'],['Trilha completa','Conclua as 12 etapas de um método.',C.METHODS.some(m=>doneCount(m.id)===12),'◇'],['Modelador','Conclua uma missão de 3 etapas.',C.CASES.some(c=>c.tasks.every((_,i)=>p.completed[`p:${c.id}:${i}`])),'◈'],['Explorador do terminal','Resolva uma equação ou sistema.',p.labCount>0,'λ'],['Constância','Pratique em 3 dias consecutivos.',P.streak(p)>=3,'↗'],['Mente numérica',`Conclua as ${C.METHODS.length*12} etapas de estudo.`,courseDone()===C.METHODS.length*12,'Σ'],['Caçador de Raízes','Vença uma fase na Calculândia.',(calcSummary()||{wins:0}).wins>=1,'▲'],['Turma reunida','Jogue uma partida completa de Quem Divergiu?',qdSummary().games>=1,'ε'],['Autonomia','Conquiste 3 estrelas em 10 atividades.',Object.values(p.completed).filter(c=>c.stars===3).length>=10,'★'],['Combo','Acerte 3 desafios seguidos.',(p.best||0)>=3,'⚡'],['Desbravador','Complete 3 mundos da jornada.',C.METHODS.filter(m=>doneCount(m.id)===12).length>=3,'⛰'],['Estilo próprio','Compre uma roupa para Raiz e Pivô no camarim.',(p.owned||[]).length>0,'✿']];
function confirmBox(){if(s.confirm==='reset')return `<div class="confirm card" role="alertdialog" aria-labelledby="confirm-title"><h3 id="confirm-title">Apagar todo o progresso local?</h3><p>Exporte um backup antes, se quiser guardá-lo. Essa ação não pode ser desfeita.</p><div class="row-actions">${btn('Apagar progresso','confirm-yes','danger')}${btn('Cancelar','confirm-no','ghost')}</div></div>`;if(s.confirm==='restore'&&s.pendingRestore)return `<div class="confirm card" role="alertdialog" aria-labelledby="confirm-title"><h3 id="confirm-title">Substituir o progresso atual pelo backup?</h3><p>Trilhas: ${Object.keys(s.pendingRestore.trilhas.completed||{}).length} atividades concluídas e ${s.pendingRestore.trilhas.xp??0} XP.${s.pendingRestore.full&&TR?(()=>{const d=TR.describe(s.pendingRestore.treino);return ` Treino: ${d.exercises} exercícios com progresso e ${d.provas} ${d.provas===1?'prova':'provas'} no histórico.`;})():' Este arquivo é de uma versão anterior e só traz as trilhas; o Treino atual fica como está.'}</p><div class="row-actions">${btn('Substituir progresso','confirm-yes','primary')}${btn('Cancelar','confirm-no','ghost')}</div></div>`;return '';}
// Camarim (v11): o que as moedas compram. Só enfeite: nenhuma roupa muda a dificuldade ou a nota.
function camarim(){const MZ=window.NumeraMascotes;if(!MZ)return '';const on=p.outfit||[],owned=p.owned||[],coins=p.coins||0;
 return `<section class="card camarim" aria-labelledby="cam-t"><div class="cam-stage">${MZ.svg(on,'cam')}</div><div class="cam-body"><span class="eyebrow">Camarim</span><h2 id="cam-t">Raiz e Pivô</h2><p>A Raiz é um rabanete: a raiz que a gente procura em toda equação. O Pivô é um bloquinho de matriz de luvas de boxe, o pivô da Eliminação de Gauss, que gira quando dança. Os dois torcem por você nos desafios e, a cada 3 acertos seguidos, o Pivô soca a caixa Σ e caem moedas. Troque as moedas por roupas para o casal.</p>
 <div class="cam-items">${MZ.ITEMS.map(it=>{const has=owned.includes(it.id),worn=on.includes(it.id);return `<div class="cam-item ${worn?'worn':''}"><b>${it.name}</b><small>${it.who==='raiz'?'para a Raiz':'para o Pivô'}</small>${has?btn(worn?'Tirar':'Vestir','equip',worn?'ghost':'blue',`data-id="${it.id}" aria-pressed="${worn}"`):btn(`<span class="coin-ico" aria-hidden="true">√</span> ${it.price}`,'buy',coins>=it.price?'primary':'ghost',`data-id="${it.id}" aria-label="Comprar ${it.name} por ${it.price} moedas" ${coins>=it.price?'':'disabled'}`)}</div>`;}).join('')}</div>
 <p class="fine">Moedas: +2 por etapa nova, +5 por etapa de missão, +5 a cada 3 acertos seguidos (com pelo menos uma atividade nova no meio), +10 por nível e +30 por mundo completo.</p></div></section>`;}
function progress(){const three=Object.values(p.completed).filter(v=>v.stars===3).length,badges=badgeList();return `<div class="wrap page-body">${heading('Progresso','Cada conquista tem uma história','Conclusão mede as atividades feitas. Estrelas registram sua melhor tentativa e não são uma certificação de domínio.')}
 <div class="stat-row"><div class="stat card"><span>Experiência · nível ${level()}</span><b>${p.xp}<small> XP</small></b>${bar(p.xp%200,200,'Progresso até o próximo nível')}</div><div class="stat card"><span>Atividades concluídas</span><b>${totalDone()}<small>/${visibleIds().length}</small></b></div><div class="stat card"><span>Com 3 estrelas</span><b>${three}</b></div><div class="stat card"><span>Moedas · melhor sequência: ${p.best||0}</span><b>${p.coins||0}</b></div></div>
 ${camarim()}
 ${treinoCard()}
 <div class="two-col"><section class="card"><h2>Seu mapa de aprendizado</h2>${C.METHODS.map(m=>`<div class="method-progress"><span class="symbol small tone-${m.id}" aria-hidden="true">${safe(m.symbol)}</span><div><div class="mp-row"><span>${m.title}</span><b>${doneCount(m.id)}/12</b></div>${bar(doneCount(m.id),12,'Progresso em '+m.title)}</div></div>`).join('')}</section><section class="card"><h2>Últimos 14 dias</h2><p>Atividades diferentes concluídas em cada dia.</p><div class="calendar">${Array.from({length:14},(_,i)=>{const d=new Date();d.setDate(d.getDate()-13+i);const key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,n=p.activity[key]?.length||0;return `<div class="day ${n?'done':''} ${n>=3?'goal':''}" title="${key}: ${n} atividades"><span>${d.getDate()}</span><b>${n||'·'}</b></div>`;}).join('')}</div><div class="callout"><b>${P.streak(p)} ${P.streak(p)===1?'dia':'dias'} de sequência</b><p>Conta dias consecutivos com atividades concluídas, terminando hoje ou ontem.</p></div></section></div>
 <div class="section-head row tight"><h2>Conquistas</h2>${tag(`${badges.filter(b=>b[2]).length} de ${badges.length} desbloqueadas`)}</div><div class="badge-grid">${badges.map(([t,d,yes,mark])=>`<article class="card badge ${yes?'earned':'locked'}"><span class="badge-mark" aria-hidden="true">${mark}</span><h3>${t}</h3><p>${d}</p><small>${yes?'Desbloqueada ✓':'Em construção'}</small></article>`).join('')}</div>
 <section class="card backup"><div><h3>Leve seu progresso com você</h3><p>O backup é um único arquivo com tudo: trilhas, XP, Treino, provas, revisões e o que você já leu. Importe em outro navegador. Os dados ficam neste dispositivo.</p></div><div class="row-actions">${btn('Exportar backup','backup','ghost')}<label class="btn ghost" for="restore">Importar backup</label><input class="sr-only" type="file" id="restore" accept="application/json,.json">${btn('Reiniciar progresso','reset','danger-ghost')}</div></section>${confirmBox()}</div>`;}

/* ---------- Gráficos ---------- */
function graph(fn,r,input={},row=null){
 // Só marca raízes no eixo quando a execução foi aceita: uma quase-raiz não ganha a bolinha verde de raiz.
 const roots=r.converged===false&&!r.roots?[]:r.roots?.map(x=>x.root)||[r.root],center=typeof r.root==='number'?r.root:0;
 let a=Number(input.a),b=Number(input.b);if(!Number.isFinite(a)||!Number.isFinite(b)||a>=b){a=center-2;b=center+2;}
 if(row&&Number.isFinite(row.a)){a=Math.min(a,row.a);b=Math.max(b,row.b);}
 const span=Math.max(b-a,.2),lo=Math.min(a,center)-span*.25,hi=Math.max(b,center)+span*.25,W=640,H=290,L=48,R=18,T=22,B=38;
 const pts=[];for(let i=0;i<=240;i++){const x=lo+(hi-lo)*i/240;let y;try{y=fn(x);}catch(_){y=NaN;}pts.push([x,y]);}
 const ys=pts.map(q=>q[1]).filter(Number.isFinite).sort((u,v)=>u-v);if(!ys.length)return '<p class="fine">Sem pontos reais finitos para desenhar nesta faixa.</p>';
 let low=Math.min(0,ys[Math.floor(ys.length*.03)]),high=Math.max(0,ys[Math.floor(ys.length*.97)]);if(!(high-low>1e-300)){low-=1;high+=1;}const pad=(high-low)*.12;low-=pad;high+=pad;
 // Escala do eixo vertical: funções minúsculas (1e-20·(x²+1)) ou enormes ganham um fator 10ᴱ no rótulo, em vez de virar uma reta sobre o eixo.
 const mag=Math.max(Math.abs(low),Math.abs(high)),E=mag<1e-3||mag>=1e6?Math.floor(Math.log10(mag)):0,unit=Math.pow(10,E),sup=n=>String(n).replace(/[-0-9]/g,c=>'⁻⁰¹²³⁴⁵⁶⁷⁸⁹'['-0123456789'.indexOf(c)]);
 const X=x=>L+(x-lo)/(hi-lo)*(W-L-R),Y=y=>H-B-(y-low)/(high-low)*(H-T-B);
 let path='',last=null;for(const [x,y]of pts){if(!Number.isFinite(y)||y<low-(high-low)*2||y>high+(high-low)*2){last=null;continue;}const px=X(x),py=Y(y);path+=(last&&Math.abs(py-last)<H*.6?'L':'M')+px.toFixed(2)+' '+py.toFixed(2)+' ';last=py;}
 let overlay='';if(r.interval&&!row)for(const [v,l] of [[r.interval.a,'a'],[r.interval.b,'b']])if(v>=lo&&v<=hi)overlay+=`<path class="g-iv" d="M${X(v)} ${T}V${H-B}"/><text class="g-label g-iv-label" x="${X(v)+5}" y="${T+14}">${l}</text>`;
 if(row?.a!==undefined)overlay+=`<rect class="g-band" x="${X(row.a)}" y="${T}" width="${Math.max(0,X(row.b)-X(row.a))}" height="${H-T-B}"/>`;
 if(row?.kept!==undefined&&Number.isFinite(row.fa)&&Number.isFinite(row.fb))overlay+=`<path class="g-chord" d="M${X(row.a)} ${Y(row.fa)}L${X(row.b)} ${Y(row.fb)}"/><circle class="g-point" cx="${X(row.a)}" cy="${Y(row.fa)}" r="4"/><circle class="g-point" cx="${X(row.b)}" cy="${Y(row.fb)}" r="4"/>`;
 if(row?.derivative!==undefined){const xx=row.previous,yy=fn(xx),d=row.derivative;overlay+=`<path class="g-tangent" d="M${X(lo)} ${Y(yy+d*(lo-xx))}L${X(hi)} ${Y(yy+d*(hi-xx))}"/>`;}
 if(row?.f0!==undefined&&row.x1!==row.x0){const slope=(row.f1-row.f0)/(row.x1-row.x0);overlay+=`<path class="g-tangent" d="M${X(lo)} ${Y(row.f0+slope*(lo-row.x0))}L${X(hi)} ${Y(row.f0+slope*(hi-row.x0))}"/>`;}
 const marker=row&&typeof row.x==='number'?row.x:center;
 return `<div class="chart"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Gráfico aproximado de f(x). Faixa ${num(lo)} a ${num(hi)}.${E?` Eixo vertical em unidades de 10 elevado a ${E}.`:''} O desenho não prova continuidade."><defs><clipPath id="plotclip"><rect x="${L}" y="${T}" width="${W-L-R}" height="${H-T-B}"/></clipPath></defs>${Array.from({length:5},(_,i)=>{const v=low+(high-low)*i/4;return `<path class="g-grid" d="M${L} ${Y(v)}H${W-R}"/><text x="${L-8}" y="${Y(v)+4}" text-anchor="end" class="g-label">${safe(Number((v/unit).toPrecision(3)).toLocaleString('pt-BR'))}</text>`;}).join('')}<path class="g-axis" d="M${L} ${Y(0)}H${W-R}"/><g clip-path="url(#plotclip)">${overlay}<path class="g-curve" d="${path}"/>${roots.filter(v=>v>=lo&&v<=hi).map(v=>`<circle class="g-root" cx="${X(v)}" cy="${Y(0)}" r="4"/>`).join('')}${Number.isFinite(fn(marker))?`<circle class="g-point big" cx="${X(marker)}" cy="${Y(fn(marker))}" r="6"/>`:''}</g>${Array.from({length:5},(_,i)=>{const v=lo+(hi-lo)*i/4;return `<text class="g-label" x="${X(v)}" y="${H-12}" text-anchor="middle">${safe(Number(v.toPrecision(3)).toLocaleString('pt-BR'))}</text>`;}).join('')}<text x="${W-R-4}" y="${Y(0)-8}" text-anchor="end" class="g-label">x</text><text x="${L}" y="16" class="g-label">${E?'f(x), em unidades de 10'+sup(E):'f(x)'}</text></svg></div>`;
}

/* Diagrama em teia do Ponto Fixo: y = g(x), y = x e os degraus xₖ → g(xₖ) → xₖ₊₁. */
function cobweb(g,r,row=null){
 const its=r.iterations,upto=row?Math.max(0,its.indexOf(row)):its.length-1,shown=its.slice(0,Math.min(its.length,Math.max(upto+1,1)));
 const xs=its.slice(0,12).map(t=>t.x).concat(its.slice(0,12).map(t=>t.gx)).filter(Number.isFinite);if(!xs.length)return '';
 let lo=Math.min(...xs),hi=Math.max(...xs);const span=Math.max(hi-lo,.2);lo-=span*.3;hi+=span*.3;
 const W=640,H=320,L=48,R=18,T=18,B=38,X=x=>L+(x-lo)/(hi-lo)*(W-L-R),Y=y=>H-B-(y-lo)/(hi-lo)*(H-T-B);
 let path='',pen=false;for(let i=0;i<=240;i++){const x=lo+(hi-lo)*i/240;let y;try{y=g(x);}catch(_){y=NaN;}if(!Number.isFinite(y)||y<lo-(hi-lo)||y>hi+(hi-lo)){pen=false;continue;}path+=(pen?'L':'M')+X(x).toFixed(1)+' '+Y(y).toFixed(1)+' ';pen=true;}
 let web=`M${X(shown[0].x).toFixed(1)} ${Y(lo).toFixed(1)}V${Y(shown[0].x).toFixed(1)}`;
 for(let k=0;k<shown.length;k++){const t=shown[k];if(!Number.isFinite(t.gx))break;web+=`V${Y(t.gx).toFixed(1)}`;if(k<shown.length-1)web+=`H${X(t.gx).toFixed(1)}`;}
 const cur=shown[shown.length-1],ticks=Array.from({length:5},(_,i)=>lo+(hi-lo)*i/4);
 return `<div class="chart"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Diagrama em teia do Ponto Fixo: curva y = g(x), diagonal y = x e ${shown.length} iterações"><defs><clipPath id="webclip"><rect x="${L}" y="${T}" width="${W-L-R}" height="${H-T-B}"/></clipPath></defs>${ticks.map(v=>`<path class="g-grid" d="M${L} ${Y(v).toFixed(1)}H${W-R}"/><text class="g-label" x="${L-8}" y="${(Y(v)+4).toFixed(1)}" text-anchor="end">${safe(short(v))}</text><text class="g-label" x="${X(v).toFixed(1)}" y="${H-12}" text-anchor="middle">${safe(short(v))}</text>`).join('')}<g clip-path="url(#webclip)"><path class="g-diag" d="M${X(lo)} ${Y(lo)}L${X(hi)} ${Y(hi)}"/><path class="g-curve" d="${path}"/><path class="g-web" d="${web}"/>${Number.isFinite(cur.gx)?`<circle class="g-point big" cx="${X(cur.x).toFixed(1)}" cy="${Y(cur.gx).toFixed(1)}" r="6"/>`:''}</g><text class="g-label" x="${W-R-4}" y="${(Y(hi)+14).toFixed(1)}" text-anchor="end">y = x</text><text class="g-label" x="${L}" y="14">y = g(x)</text></svg></div>`;}

/* ---------- Terminal ---------- */
function field(id,label,extra=''){return `<label class="field" for="${id}">${label}<input id="${id}" value="${safe(s[id])}" autocomplete="off" ${extra}></label>`;}
const EXAMPLES=[['Cúbica','x^3-x-2=0'],['Duas raízes','x^2-2=0'],['Cosseno','cos(x)-x=0'],['Equação de Kepler','x = 1 + 0.5sin(x)'],['Raiz repetida','(x-1.3)^2=0'],['Com intervalo','x^3 - 9x + 3 = 0 em [0; 1]'],['Sistema 2×2','2x+y=5\nx+3y=6'],['Sistema 3×3','10x-y+2z=6\n-x+11y-z=22\n2x-y+10z=-10']];
// ---------- Método e intervalo [a, b] (v10.1): os dados do exercício ficam à vista, logo abaixo da equação ----------
const NAMES={auto:'Automático',bisection:'Bisseção',falseposition:'Falsa Posição',newton:'Newton-Raphson',secant:'Secante',fixedpoint:'Ponto Fixo',gauss:'Eliminação de Gauss',seidel:'Gauss-Seidel'};
const EXAMPLE_IV='x^3 - 9x + 3 = 0 em [0; 1]';
const THE={bisection:'a Bisseção',falseposition:'a Falsa Posição',newton:'o Newton-Raphson',secant:'a Secante',fixedpoint:'o Ponto Fixo'};
const epsText=v=>{const e=Math.round(Math.log10(v));return Math.abs(v/Math.pow(10,e)-1)<1e-9?'10'+String(e).replace(/[-0-9]/g,c=>'⁻⁰¹²³⁴⁵⁶⁷⁸⁹'['-0123456789'.indexOf(c)]):num(v);};
const PARAM_HINTS={auto:`Com intervalo, a busca e a comparação de métodos ficam dentro de [a, b]. Também dá para escrever junto da equação: <code>${EXAMPLE_IV}</code>.`,
 bisection:'A Bisseção começa em [a, b] e exige f(a) e f(b) com sinais opostos. Ponto ou vírgula decimal; pi também vale (ex.: pi/2).',
 falseposition:'A Falsa Posição começa em [a, b] e exige f(a) e f(b) com sinais opostos. Ponto ou vírgula decimal; pi também vale (ex.: pi/2).',
 newton:'Sem x₀, o Newton começa na ponta do intervalo onde f(x)·f″(x) > 0 (condição de Fourier) ou, se nenhuma servir, no ponto médio.',
 secant:'Sem x₀ e x₁, a Secante começa pelas pontas a e b do intervalo.',
 fixedpoint:'Sem x₀, o Ponto Fixo começa no ponto médio do intervalo, e o Numera confere se max |g′| < 1 ali. g(x) vazio: usa o lado direito de x = …'};
function paramsRow(){
 if(C.isHidden&&C.isHidden(s.algorithm))s.algorithm='auto'; // método escondido (ex.: estado antigo) volta ao automático
 const root=s.mode==='root',alg=s.algorithm,bracket=alg==='bisection'||alg==='falseposition';
 const opts=[['auto','Automático (comparar e escolher)'],...C.METHODS.filter(m=>root!==['gauss','seidel'].includes(m.id)).map(m=>[m.id,m.title])];
 const inp=(id,label,ph,cls='')=>`<label class="tp-field ${cls}" for="${id}"><span>${label}</span><input id="${id}" value="${safe(s[id]??'')}" placeholder="${ph}" autocomplete="off" spellcheck="false"></label>`;
 let html=`<label class="tp-field tp-method" for="algorithm"><span>Método</span><select id="algorithm">${opts.map(([id,t])=>`<option value="${id}" ${alg===id?'selected':''}>${t}</option>`).join('')}</select></label>`;
 if(root){
  html+=`<div class="tp-interval" role="group" aria-labelledby="iv-label"><span class="tp-label" id="iv-label">Intervalo [a, b] <small>${bracket?'obrigatório':'opcional'}</small></span><div class="tp-bracket"><span aria-hidden="true">[</span><label class="sr-only" for="a">Ponta a (esquerda) do intervalo</label><input id="a" value="${safe(s.a??'')}" placeholder="a" autocomplete="off" spellcheck="false"><span aria-hidden="true">;</span><label class="sr-only" for="b">Ponta b (direita) do intervalo</label><input id="b" value="${safe(s.b??'')}" placeholder="b" autocomplete="off" spellcheck="false"><span aria-hidden="true">]</span>${String(s.a||'').trim()||String(s.b||'').trim()?`<button type="button" class="tp-clear" data-act="interval-clear" aria-label="Limpar o intervalo" title="Limpar o intervalo">×</button>`:''}</div></div>`;
  if(['newton','secant','fixedpoint'].includes(alg))html+=inp('x0','x₀','automático','tp-num');
  if(alg==='secant')html+=inp('x1','x₁','automático','tp-num');
  if(alg==='fixedpoint')html+=inp('g','g(x)','vazio = lado direito de x = …','tp-wide');
  if(alg!=='auto')html+=inp('tolerance','Tolerância ε','1e-6','tp-num');
 }else if(alg==='seidel')html+=inp('initial','Vetor inicial','vazio = zeros','tp-wide');
 const hint=root?PARAM_HINTS[alg]:'';
 return `<div class="terminal-params">${html}</div>${hint?`<p class="tp-hint">${hint}</p>`:''}`;}
const clearInputs=()=>{for(const k of ['a','b','x0','x1','g'])s[k]='';};
const sig5=v=>num(Number(Number(v).toPrecision(5)));
const ivText=I=>`[${num(I.a)}; ${num(I.b)}]`;
const ivField=v=>String(Number(v)).replace('.',','); // para os campos a e b: vírgula decimal, sem separador de milhar
const listJoin=a=>a.length<2?a.join(''):a.slice(0,-1).join(', ')+' e '+a[a.length-1];
// O intervalo dos campos a e b (texto) vira números. Vazio nos dois = sem intervalo.
function readInterval(){const ta=String(s.a??'').trim(),tb=String(s.b??'').trim();if(!ta&&!tb)return null;
 if(!ta||!tb)throw Error('Preencha as duas pontas do intervalo, a e b, ou deixe as duas vazias.');
 const a=M.constValue(ta,'Ponta a do intervalo'),b=M.constValue(tb,'Ponta b do intervalo');
 if(!(a<b))throw Error(`O intervalo precisa ter a < b. Você informou a = ${num(a)} e b = ${num(b)}.`);
 return {a,b};}
function intervalValues(fn,I){const at=x=>{try{const y=fn(x);return Number.isFinite(y)?y:NaN;}catch(_){return NaN;}},fa=at(I.a),fb=at(I.b);
 for(const [v,fv,k] of [[I.a,fa,'a'],[I.b,fb,'b']])if(!Number.isFinite(fv))throw Error(`f não tem valor real finito na ponta ${k} = ${num(v)} do intervalo. Escolha um intervalo dentro do domínio da função.`);
 return {...I,fa,fb,sign:fa===0||fb===0?'zero':Math.sign(fa)!==Math.sign(fb)?'troca':'mesmo'};}
// Sem intervalo: a busca automática acha raízes e propõe intervalos "redondos" com troca de sinal, para um clique.
function suggestIntervals(source,fn){try{const sr=M.smartRoot(source,{min:numeric(s.min),max:numeric(s.max)}),out=[];
 for(const rt of sr.roots){if(rt.certification&&rt.certification.status!=='certificada')continue;const st=M.convergenceStart(fn,rt.root);if(st&&!out.some(o=>o.a===st.a&&o.b===st.b))out.push({a:st.a,b:st.b});if(out.length>=3)break;}
 return out;}catch(_){return [];}}
function sameSignError(name,fn,source,I){const ch=M.signChanges(fn,I.a,I.b);s.errorFix=ch.slice(0,4).map(c=>({a:c.a,b:c.b}));
 let msg=`f(a) e f(b) têm o mesmo sinal: f(${num(I.a)}) ≈ ${sig5(I.fa)} e f(${num(I.b)}) ≈ ${sig5(I.fb)}. Assim a ${name} não pode começar, porque o Teorema do Valor Intermediário não garante raiz em ${ivText(I)}: pode não haver nenhuma, ou haver um número par delas.`;
 if(ch.length)msg+=` Dentro do intervalo, f troca de sinal em ${listJoin(ch.map(ivText))}: use ${ch.length>1?'um desses pedaços':'esse pedaço'}.`;
 else{let multi=null;try{const sr=M.smartRoot(source,{min:I.a,max:I.b});multi=sr.roots.find(r=>r.certification&&r.certification.status==='multipla');}catch(_){}
  msg+=multi?` A curva toca o eixo em x ≈ ${sig5(multi.root)} sem trocar de sinal (raiz de multiplicidade par): a ${name} não encontra esse tipo de raiz. Use o Newton ou o automático.`:' A busca também não encontrou raiz dentro dele: confira o intervalo do exercício.';}
 return Error(msg);}
// Automático com intervalo: busca só dentro de [a, b]. Com uma única raiz e troca de sinal, todos os métodos partem dos dados do exercício.
function autoInInterval(source,fn,I,options){let sr;if(I.b-I.a>1e6)throw Error('No automático, o intervalo pode ter largura de até 1.000.000. Para um intervalo maior, escolha um método no campo Método.');
 try{sr=M.smartRoot(source,{...options,min:I.a,max:I.b});}catch(e){throw Error(`Nenhuma raiz encontrada no intervalo ${ivText(I)}${I.sign==='mesmo'?` (f(a) ≈ ${sig5(I.fa)} e f(b) ≈ ${sig5(I.fb)} têm o mesmo sinal)`:''}. A busca é amostrada: isso não prova que não exista raiz ali, mas vale conferir o intervalo do exercício.`);}
 if(I.sign!=='troca'||sr.roots.length!==1)return {...sr,note:(sr.roots.length>1?`O intervalo ${ivText(I)} contém ${sr.roots.length} raízes; todas aparecem em "Outras candidatas". `:'')+sr.note};
 const st=M.intervalStart(fn,I.a,I.b),cmp=M.compareRoot(fn,st,{...options,tolerance:Math.min(options.tolerance,1e-12)}),w=cmp.winner;
 if(!w||Math.abs(w.r.root-sr.root)>1e-6*(1+Math.abs(sr.root)))return sr;
 return {...w.r,roots:sr.roots,search:sr.search,comparisons:cmp.comparisons,evaluations:w.evaluations,inputs:{a:I.a,b:I.b,x0:st.x0,x1:st.x1},
  recommendation:`Todos os métodos partiram dos seus dados: o intervalo ${ivText(I)} na Bisseção e na Falsa Posição, x₀ = ${num(st.x0)} no Newton (${st.why}) e x₀ = ${num(st.x0)}, x₁ = ${num(st.x1)} na Secante. Venceu a execução aceita com menos avaliações de f, com resíduo de até 1e-12. Não mede tempo real.`,
  note:(w.r.note?w.r.note+' ':'')+`A busca dentro de ${ivText(I)} encontrou uma única raiz.`};}
// Raízes: o intervalo (dos campos ou escrito na equação) vale para todos os métodos.
function solveRoot(source,options){
 const split=M.splitInterval(source);
 if(split.interval){s.a=split.interval.ta;s.b=split.interval.tb;s.source=split.equation;source=split.equation;}
 const fn=M.parseFunction(source),alg=s.algorithm,has=k=>String(s[k]??'').trim()!=='',notes=[];
 let I=readInterval();if(I)I=intervalValues(fn,I);const start=I?M.intervalStart(fn,I.a,I.b):null;
 const need=msg=>{s.errorFix=suggestIntervals(source,fn);throw Error(msg+(s.errorFix.length?` Para esta equação, a busca encontrou troca de sinal em ${listJoin(s.errorFix.map(ivText))}.`:''));};
 let r;
 if(alg==='auto')r=I?autoInInterval(source,fn,I,options):M.smartRoot(source,{...options,min:numeric(s.min),max:numeric(s.max)});
 else if(alg==='bisection'||alg==='falseposition'){
  if(!I)need(`A ${NAMES[alg]} precisa de um intervalo [a, b] com f(a) e f(b) de sinais opostos. Preencha a e b logo abaixo da equação, ou escreva o intervalo junto dela, como ${EXAMPLE_IV}.`);
  if(I.sign==='mesmo')throw sameSignError(NAMES[alg],fn,source,I);
  r=alg==='bisection'?M.bisection(fn,I.a,I.b,options):M.falsePosition(fn,I.a,I.b,options);
  r.inputs={a:I.a,b:I.b,x0:start.x0,x1:start.x1};
 }else{
  let x0=has('x0')?numeric(s.x0):null,x1=has('x1')?numeric(s.x1):null;
  if(alg==='newton'){if(x0===null){if(!I)need('O Newton-Raphson precisa de um ponto inicial x₀ ou de um intervalo [a, b] (aí o x₀ é escolhido dentro dele).');x0=start.x0;notes.push(`x₀ = ${num(x0)}: ${start.why}.`);}r=M.newton(fn,x0,options);}
  else if(alg==='secant'){
   if(x0===null||x1===null){if(!I)need('A Secante precisa de dois pontos, x₀ e x₁, ou de um intervalo [a, b] (aí ela começa pelas duas pontas).');
    if(x0===null&&x1===null){x0=I.a;x1=I.b;notes.push(`x₀ = a = ${num(I.a)} e x₁ = b = ${num(I.b)}: as pontas do intervalo.`);}
    else if(x1===null){x1=x0===I.b?I.a:I.b;notes.push(`x₁ = ${num(x1)}: ponta do intervalo.`);}
    else{x0=x1===I.a?I.b:I.a;notes.push(`x₀ = ${num(x0)}: ponta do intervalo.`);}}
   if(x0===x1)throw Error('A Secante precisa de dois pontos diferentes: x₀ ≠ x₁.');r=M.secant(fn,x0,x1,options);}
  else{const gsrc=iterationFunction(source,s.g),g=M.parseFunction(gsrc);
   if(x0===null){if(!I)need('O Ponto Fixo precisa de um ponto inicial x₀ ou de um intervalo [a, b] (aí ele começa no ponto médio).');x0=I.a+(I.b-I.a)/2;notes.push(`x₀ = ${num(x0)}: ponto médio do intervalo.`);}
   r=M.fixedPoint(g,x0,options);r.g=gsrc;
   if(I){const chk=M.fixedPointCheck(g,I.a,I.b);if(chk)notes.push(chk.maxD<1&&chk.maps?`Em ${ivText(I)}, max |g′| ≈ ${sig5(chk.maxD)} < 1 e g leva o intervalo nele mesmo: pelo teorema do ponto fixo, há um único ponto fixo ali e a iteração converge a partir de qualquer x₀ do intervalo.`:chk.maxD>=1?`Em ${ivText(I)}, max |g′| ≈ ${sig5(chk.maxD)} ≥ 1: a convergência não é garantida neste intervalo. Se divergir, reescreva x = g(x) de outra forma.`:`Em ${ivText(I)}, |g′| < 1 (máximo ≈ ${sig5(chk.maxD)}), mas g leva parte do intervalo para fora dele: a convergência não é garantida para todo x₀.`);}}
  if(I&&(x0<I.a||x0>I.b))notes.push(`Atenção: x₀ = ${num(x0)} está fora do intervalo ${ivText(I)}.`);
  r.inputs={a:I?I.a:NaN,b:I?I.b:NaN,x0,x1:x1??(I?(x0===I.b?I.a:I.b):NaN)};
 }
 if(I){const slack=1e-9*(1+Math.abs(I.a)+Math.abs(I.b)),inside=Number.isFinite(r.root)&&r.root>=I.a-slack&&r.root<=I.b+slack;
  if(alg!=='auto'&&r.converged){const ch=M.signChanges(fn,I.a,I.b),others=ch.filter(c=>!(c.a<=r.root&&r.root<=c.b));if(ch.length>1&&others.length){notes.push(`f troca de sinal ${ch.length} vezes em ${ivText(I)}: há mais de uma raiz no intervalo, e ${THE[r.method]} encontrou só uma. As outras ficam em ${listJoin(others.map(ivText))}.`);r.intervalFix=others.slice(0,4).map(c=>({a:c.a,b:c.b}));}}
  if(r.converged&&!inside)notes.push(`A raiz encontrada, x ≈ ${num(r.root)}, está fora do intervalo ${ivText(I)}: ${THE[r.method]} saiu do intervalo e convergiu para outra raiz. Para ficar dentro dele, use a Bisseção ou outro ponto inicial.`);
  if(alg==='bisection')notes.push(`Pelo critério da largura do intervalo, a Bisseção precisaria de n ≥ log₂((b − a)/ε) = ${M.bisectionBound(I.a,I.b,options.tolerance)} iterações para o intervalo ficar menor que ε = ${epsText(options.tolerance)}. O Numera usa o critério |f(x)| ≤ ε${r.converged&&r.iterations[r.iterations.length-1].i>0?`, atingido aqui na iteração ${r.iterations[r.iterations.length-1].i}`:''}; compare com o critério pedido no exercício.`);
  r.interval={...I,inside,start};}
 r.intervalNotes=notes;return {r,source};}
function lab(){return `<div class="wrap page-body">${heading('Terminal','Digite a equação. Siga o cálculo.','Equações de uma variável e sistemas lineares. A resposta vem com os passos, a comparação entre métodos e a verificação.')}
 <form id="terminal-form" class="terminal"><div class="terminal-top"><span class="dots" aria-hidden="true"><i></i><i></i><i></i></span><span>numera / laboratório</span><span class="engine-status">● motor local</span></div><div class="terminal-body"><p class="terminal-welcome"><span>›</span> Equações reais e sistemas lineares. Ctrl / ⌘ + Enter executa.</p><label for="source" class="sr-only">Equação ou sistema de equações</label><div class="terminal-entry"><span class="prompt-symbol" aria-hidden="true">λ</span><textarea id="source" rows="${s.source.includes('\n')?'4':'2'}" spellcheck="false" autocomplete="off" placeholder="x³ − x − 2 = 0">${safe(s.source)}</textarea></div>${paramsRow()}<div class="terminal-actions"><div class="terminal-examples"><span>Exemplos</span>${EXAMPLES.map(([label],i)=>`<button type="button" data-act="example" data-index="${i}">${label}</button>`).join('')}</div><button class="btn primary" type="submit" id="solve-btn">${icon('lab')} Resolver</button></div></div></form>
 <div class="terminal-tools">${tabs([['root','Raízes de funções'],['system','Sistemas lineares']],s.mode,'mode')}<div class="row-actions">${btn('Sintaxe e comandos','help','text')}${btn('Histórico ('+p.history.length+')','history','text')}</div></div>
 ${s.historyOpen?`<section class="card history"><h3>Últimas resoluções neste navegador</h3>${p.history.length?p.history.map((h,i)=>`<button type="button" data-act="history-load" data-index="${i}"><code>${safe(h.source.replace(/\n/g,' ; '))}</code><small>${safe(h.summary)} · ${safe(h.date)}</small></button>`).join(''):'<p>Nenhuma resolução registrada ainda.</p>'}</section>`:''}
 ${s.help?`<section class="card help-panel"><h3>Como conversar com o terminal</h3><div class="glossary-grid"><div><h4>Uma variável real</h4><code>2x + cos(x) = 3</code><p>Use x, parênteses, pi, e, sin/sen, cos, tan/tg, exp, ln, log (base 10), sqrt e abs. Para elevar, use a tecla xⁿ ou digite ^ no teclado: o expoente sobe sozinho, como em x². Ângulos em radianos. Decimais com ponto ou vírgula.</p></div><div><h4>Sistemas lineares</h4><code>2x+y=5<br>x+3y=6</code><p>De 2 a 6 equações, uma por linha; x, y, z, u, v, w ou x1…x6. Também aceita matriz: <code>2, 1 | 5</code>. Na matriz, use ponto decimal.</p></div><div><h4>Intervalo [a, b]</h4><code>${EXAMPLE_IV}</code><p>Preencha a e b logo abaixo da equação ou escreva o intervalo no fim dela: [a; b], [a, b], “no intervalo [a, b]” ou “x ∈ [a, b]”. Com vírgula decimal, separe as pontas com ponto e vírgula: [1,5; 2,5]. Pontas como pi/2 também valem. O intervalo vale para todos os métodos.</p></div><div><h4>Comandos</h4><code>/help · /history · /clear</code><p>O terminal é um solucionador numérico local. Não interpreta linguagem natural, integrais, EDOs ou raízes complexas.</p></div><div><h4>Busca automática</h4><p>801 pontos amostrados na faixa escolhida, refino local perto dos mínimos de |f| e das bordas do domínio, e até 400 candidatas testadas. Pode encontrar várias raízes, mas não garante encontrar todas. Ajuste a faixa para investigar outras regiões.</p></div></div></section>`:''}
 <details class="card advanced"><summary>Ajustes avançados <span>${s.mode==='root'?'limite de iterações e faixa de busca':'tolerância, iterações e vetor inicial'}</span></summary><div class="advanced-grid">${s.mode==='root'?`${field('maxIterations','Limite de iterações (1–500)')}${field('min','Busca sem intervalo: mínimo')}${field('max','Busca sem intervalo: máximo')}`:`${field('tolerance','Tolerância (1e-12 a <1)')}${field('maxIterations','Limite de iterações (1–500)')}${s.algorithm==='seidel'?'':field('initial','Vetor inicial (vazio = zeros)')}`}</div><p class="fine">${s.mode==='root'?'Sem intervalo, a busca automática amostra a faixa [mínimo, máximo] e compara Bisseção, Falsa Posição, Newton e Secante; com intervalo, ela fica dentro de [a, b]. Tolerância dos métodos manuais: resíduo absoluto |f(x)|'+(C.isHidden('fixedpoint')?'':' (no Ponto Fixo, |x − g(x)|)')+'. Na comparação automática, o alvo de resíduo é 1e-12.':'Gauss usa pivotamento parcial. A tolerância vale para o resíduo normalizado; Gauss-Seidel também exige pequena variação relativa.'}</p></details>
 ${s.error?`<div class="alert" role="alert"><strong>Não foi possível concluir.</strong> ${safe(s.error)}${s.errorFix&&s.errorFix.length?`<div class="row-actions iv-fix">${s.errorFix.map(f=>`<button type="button" class="btn ghost" data-act="use-interval" data-a="${f.a}" data-b="${f.b}">Usar ${safe(ivText(f))}</button>`).join('')}</div>`:''}</div>`:''}
 ${s.result?labResult():`<section class="card terminal-empty"><span class="empty-icon">${icon('lab')}</span><div><h3>A próxima solução começa com uma pergunta.</h3><p>Digite acima ou escolha um exemplo. Aqui aparecem a solução, os passos, a comparação de custo e a verificação.</p></div></section>`}</div>`;}
function tabs(items,active,action){return `<div class="seg" role="group" aria-label="Seções">${items.map(([id,label])=>`<button type="button" class="${active===id?'active':''}" data-act="${action}" data-id="${id}" aria-pressed="${active===id}">${label}</button>`).join('')}</div>`;}
// Estado da raiz (v10): resíduo pequeno não basta; o motor diz se há troca de sinal, raiz múltipla provável ou só uma quase-raiz.
function rootStatus(r){const st=Array.isArray(r.root)?null:r.certification?.status;
 if(r.converged&&r.interval&&!r.interval.inside)return {eyebrow:'Raiz fora do intervalo pedido',tag:'Fora de '+ivText(r.interval),color:'amber'};
 if(!st)return {eyebrow:r.converged?'Critério de parada atingido':'Critério não atingido',tag:r.converged?'✓ Tolerância atingida':'Aproximação parcial',color:r.converged?'green':'amber'};
 if(r.converged&&st==='multipla')return {eyebrow:'Raiz provável (multiplicidade par)',tag:'Sem troca de sinal: não certificada',color:'amber'};
 if(r.converged)return {eyebrow:'Raiz certificada por troca de sinal',tag:'✓ Tolerância e troca de sinal',color:'green'};
 if(st==='quase')return {eyebrow:'Quase-raiz: não é solução',tag:'|f| pequeno, mas sem raiz',color:'amber'};
 return {eyebrow:'Critério não atingido',tag:'Aproximação parcial',color:'amber'};}
function labResult(){const r=s.result,sys=Array.isArray(r.root),rs=rootStatus(r);return `<section class="card result-shell"><div class="section-head row tight"><div><span class="eyebrow ${r.converged?'ok':'warn'}">${rs.eyebrow}</span><h2 class="display">${method(r.method).title}</h2></div><div class="row-actions">${tag(rs.tag,rs.color)}${btn('Exportar resolução','export-result','ghost')}</div></div><p class="source-echo"><code>${safe(r.source)}</code></p>${r.interval?intervalEcho(r.interval):''}${tabs([['solution','Solução'],['steps','Passo a passo'],['compare','Comparar métodos'],['converge','Convergência'],['verify','Verificação'],['guide','Resolver comigo']],s.resultTab,'result-tab')}<div class="result-body">${s.resultTab==='steps'?iterationTable(r):s.resultTab==='compare'?comparison(r):s.resultTab==='converge'?convergence(r):s.resultTab==='verify'?verification(r):s.resultTab==='guide'?guide(r):`<div class="result-stats"><div class="answer-result ${r.converged&&!(r.interval&&!r.interval.inside)?'':'warn'}"><span>${r.converged&&r.interval&&!r.interval.inside?'Raiz fora do intervalo pedido':!r.converged?(r.certification?.status==='quase'?'Ponto testado: não é raiz':'Última aproximação (não validada)'):sys?'Solução aproximada':'Raiz aproximada'}</span><strong>${sys?r.root.map((v,i)=>`${r.variables?.[i]||'x'+(i+1)} = ${num(v)}`).join('<br>'):'x ≈ '+num(r.root)}</strong></div><div><span>Resíduo ${sys?'máximo':r.method==='fixedpoint'?'|x − g(x)|':'|f(x)|'}</span><strong>${num(r.residual)}</strong></div><div><span>${r.method==='gauss'?'Registros de operações':'Atualizações'}</span><strong>${updates(r)}</strong></div></div>${!sys?`${r.roots?.length>1?`<div class="root-list"><span>Outras candidatas detectadas:</span>${r.roots.map((rt,i)=>`<button type="button" class="${Math.abs(rt.root-r.root)<1e-9?'selected':''}" data-act="root" data-index="${i}">${num(rt.root)}</button>`).join('')}</div>`:''}${r.method==='fixedpoint'&&r.g?cobweb(M.parseFunction(r.g),r):graph(M.parseFunction(r.source),r,r.interval||r.initials||r.inputs)}`:''}${r.intervalNotes&&r.intervalNotes.length?`<div class="callout iv-notes"><strong>Sobre o intervalo ${safe(ivText(r.interval||{a:NaN,b:NaN}))}</strong>${r.intervalNotes.map(n=>`<p>${safe(n)}</p>`).join('')}${r.intervalFix&&r.intervalFix.length?`<div class="row-actions iv-fix">${r.intervalFix.map(f=>`<button type="button" class="btn ghost" data-act="use-interval" data-a="${f.a}" data-b="${f.b}">Resolver em ${safe(ivText(f))}</button>`).join('')}</div>`:''}</div>`:''}<div class="callout"><strong>Por que este método?</strong><p>${safe(r.recommendation||'Método escolhido manualmente. A validade desta execução depende do critério de parada e das condições fornecidas.')}</p></div><p class="fine">${safe(r.note||'')} ${sys?'Resíduo normalizado pequeno não garante pequeno erro na solução de uma matriz mal condicionada.':'Pequeno resíduo não garante que o erro em x tenha o mesmo tamanho. O gráfico é amostrado e não prova continuidade.'}</p>${r.search?`<div class="search-meta"><span>Faixa: [${num(r.search.min)}, ${num(r.search.max)}]</span><span>${r.search.samples} amostras</span><span>${r.search.tested} candidatas testadas</span><span>${r.search.totalEvaluations} avaliações no processo completo</span></div>`:''}<div class="row-actions">${btn('Entender este método '+icon('arrow'),'course','text',`data-id="${r.method}"`)}${btn('Ver todos os passos '+icon('arrow'),'result-tab','text','data-id="steps"')}</div>`}</div></section>`;}
function updates(r){if(['gauss','seidel'].includes(r.method))return r.steps;const a=r.iterations;return r.method==='secant'?Math.max(0,a[a.length-1].i-1):a[a.length-1].i;}
function iterationTable(r){if(r.method==='gauss')return `<p class="fine">Cada registro mostra uma operação efetivamente executada, incluindo trocas e retrossubstituição.</p><div class="matrix-steps">${r.iterations.map((row,i)=>`<details ${i<2?'open':''}><summary>${i+1}. ${safe(row.detail)}</summary>${matrix(row.matrix)}</details>`).join('')}</div>`;const sys=Array.isArray(r.root);return `<div class="section-head row tight"><p>${r.iterations.length} registros, incluindo as condições iniciais quando aplicáveis.</p>${btn('Baixar CSV','export-csv','text')}</div><div class="table-scroll"><table><thead><tr><th>k</th><th>${sys?'Vetor x':'Aproximação x'}</th><th>${sys?'||Ax−b||∞':r.method==='fixedpoint'?'x − g(x)':'f(x)'}</th><th>${r.method==='bisection'?'Meia largura':'Variação absoluta'}</th><th>O que foi feito</th></tr></thead><tbody>${r.iterations.map(row=>`<tr><td>${row.i}</td><td class="numeric">${Array.isArray(row.x)?row.x.map(num).join(' ; '):num(row.x)}</td><td class="numeric">${num(sys?row.residual:row.fx)}</td><td class="numeric">${num(row.error)}</td><td>${safe(row.detail)}</td></tr>`).join('')}</tbody></table></div><p class="fine">${r.method==='bisection'?'A meia largura limita o erro do ponto médio somente sob as hipóteses da Bisseção. Não é o resíduo.':r.method==='falseposition'?'Na Falsa Posição a largura de [a, b] nem sempre vai a zero (uma ponta pode ficar parada), por isso a tabela mostra a variação entre aproximações. O critério de parada é |f(x)|.':r.method==='fixedpoint'?'No Ponto Fixo, a variação |xₖ − xₖ₋₁| é igual a |xₖ₋₁ − g(xₖ₋₁)|: a coluna x − g(x) da linha anterior.':'A variação entre passos não é o erro exato. O terminal confere também o resíduo.'}</p>`;}
function comparison(r){if(!r.comparisons)return `<div class="empty-state small"><h3>Execução manual</h3><p>Você escolheu um método específico. Para comparar, escolha “Automático” no campo Método e resolva de novo${r.interval?': a comparação usa o mesmo intervalo':''}.</p></div>`;const sys=Array.isArray(r.root);return `<div class="callout"><strong>“Mais rápido” depende do problema.</strong><p>${sys?'A comparação usa um modelo simplificado de operações: Gauss ≈ 2n³/3+2n² e Gauss-Seidel ≈ 2kn². Não é uma medição de tempo.':(r.interval&&r.inputs&&!r.initials?`Todos os métodos partiram dos dados do exercício: o intervalo ${ivText(r.interval)} na Bisseção e na Falsa Posição, x₀ = ${num(r.inputs.x0)} no Newton e x₀ = ${num(r.inputs.x0)}, x₁ = ${num(r.inputs.x1)} na Secante. Contamos avaliações de f(x), incluindo as da derivada numérica do Newton, até o resíduo de 1e-12. Isso não é um benchmark de tempo.`:'Comparamos avaliações de f(x) para cada candidata, incluindo as usadas na derivada numérica de Newton. O custo da procura e das outras candidatas aparece separado. Isso não é um benchmark de tempo.')}</p></div><div class="table-scroll"><table><thead><tr><th>Método</th><th>Estado</th><th>${sys?'Custo estimado':'Avaliações de f'}</th><th>Resíduo</th><th>Observação</th></tr></thead><tbody>${r.comparisons.map(c=>`<tr class="${r.method===c.method?'winner':''}"><td><strong>${method(c.method).title}</strong>${r.method===c.method?' <span class="tag green">selecionado</span>':''}</td><td>${c.converged?'Aceito':'Não aceito'}</td><td class="numeric">${c.cost??c.evaluations??'—'}</td><td class="numeric">${num(c.residual)}</td><td>${safe(c.error||'Critério atingido nesta execução.')}</td></tr>`).join('')}</tbody></table></div><p class="fine">${sys?'Comparação entre os dois métodos existentes para o mesmo sistema.':(r.interval?'Só valem resultados dentro do intervalo. ':'Os resultados aceitos se limitam à região da candidata. ')+'As condições iniciais de cada método influenciam o custo. Em empates, usamos número de registros e resíduo.'}</p>`;}
/* Aba Convergência: os métodos aplicados aos mesmos dados iniciais, erro por iteração em escala log. */
const CONV_TITLES=()=>Object.assign(Object.fromEntries(C.METHODS.map(m=>[m.id,m.title])),{jacobi:'Jacobi (comparação)'});
function convergence(r){
 if(!window.NumeraConv)return '<p class="fine">O gráfico de convergência não foi carregado (convergencia.js).</p>';
 const sys=Array.isArray(r.root);let inp={};
 try{
  if(!r.conv){
   if(sys){const raw=s.initial.trim()?s.initial.trim().split(/[;,\s]+/).map(Number):[];const init=raw.length===r.A.length&&raw.every(Number.isFinite)?raw:r.A.map(()=>0);r.convInitial=init;r.conv=M.convergenceSystem(r.A,r.b,init);}
   else{const fn=M.parseFunction(r.source);inp=r.initials?(M.convergenceStart(fn,r.root)||r.initials):(r.inputs||{});r.convStart=inp;let g=null;if(!(C.isHidden&&C.isHidden('fixedpoint')))try{g=M.parseFunction(r.g||iterationFunction(r.source,''));}catch(_){g=null;}r.convG=g?(r.g||iterationFunction(r.source,'')):'';r.conv=M.convergenceRoot(fn,{a:inp.a,b:inp.b,x0:inp.x0,x1:inp.x1,g,reference:r.root});}
  }
 }catch(e){return `<div class="alert" role="alert"><strong>Não foi possível montar o gráfico.</strong> ${safe(e.message)}</div>`;}
 inp=r.convStart||r.inputs||{};
 const sub=sys?`Mesmo vetor inicial para os dois métodos iterativos: (${(r.convInitial||[]).map(num).join('; ')}).`:`${r.initials?'Dados de partida em volta da raiz encontrada, iguais para todos':'Os seus dados, iguais para todos'}: [a; b] = [${num(inp.a)}; ${num(inp.b)}], x₀ = ${num(inp.x0)}, x₁ = ${num(inp.x1)}${r.convG?`, g(x) = ${r.convG}`:''}.`;
 const cap=sys?`Cada linha de grade horizontal é um fator de 10 no erro ||xₖ − x*||∞. Gauss-Seidel usa os valores novos assim que os calcula; Jacobi (só para comparar) espera a iteração inteira. ${r.conv.strictDD?'Com dominância diagonal estrita, os dois convergem e o Seidel costuma precisar de menos iterações.':'Sem dominância diagonal estrita, a convergência não é garantida.'} A Eliminação de Gauss não aparece como linha: ela resolve direto, com cerca de ${r.conv.gaussOps} operações.`:`Cada linha de grade horizontal é um fator de 10 no erro |xₖ − x*|. Reta descendente = convergência linear: o erro cai por um fator fixo a cada passo (Bisseção: fator 0,5). Curva que mergulha cada vez mais rápido = ordem maior: na Secante (p ≈ 1,6) e no Newton (p = 2) as casas corretas quase dobram a cada passo.${C.isHidden('fixedpoint')?'':' O Ponto Fixo só entra quando a equação está na forma x = g(x) ou quando g(x) foi informada.'}`;
 return NumeraConv.chart(r.conv,{titles:CONV_TITLES(),highlight:r.method,highlightLabel:'método escolhido',title:'Erro por iteração, método a método',subtitle:sub,caption:safe(cap)});}
function verification(r){const sys=Array.isArray(r.root);return `<h3>Substituir a resposta é parte da solução.</h3>${sys?`<p>Calculamos Ax−b usando a matriz original.</p><div class="table-scroll"><table><thead><tr><th>Equação</th><th>Lado esquerdo Ax</th><th>Lado direito b</th><th>Diferença</th></tr></thead><tbody>${r.A.map((row,i)=>{const v=row.reduce((a,c,j)=>a+c*r.root[j],0);return `<tr><td>${i+1}</td><td class="numeric">${num(v)}</td><td class="numeric">${num(r.b[i])}</td><td class="numeric">${num(v-r.b[i])}</td></tr>`;}).join('')}</tbody></table></div><div class="formula">η = ||Ax−b||∞ / (||A||∞ ||x||∞ + ||b||∞)<br>η ≈ ${num(M.backwardError(r.A,r.b,r.root))}</div><p>O resíduo normalizado reduz a dependência da escala dos coeficientes. Ele não mede diretamente o erro nas incógnitas.</p>`:r.method==='fixedpoint'&&r.g?`<p>O Ponto Fixo para quando x e g(x) quase coincidem. Depois, a aproximação também é substituída na equação original.</p><div class="formula">x ≈ ${num(r.root)}<br>g(x) = ${safe(r.g)} ≈ ${num(M.parseFunction(r.g)(r.root))}<br>|x − g(x)| ≈ ${num(r.residual)}<br>Equação original: f(x) ≈ ${num(M.parseFunction(r.source)(r.root))}</div>${intervalExplain(r)}`:`<p>A igualdade vira f(x) = lado esquerdo − lado direito, e a aproximação é substituída nessa função.</p><div class="formula">x ≈ ${num(r.root)}<br>f(x) ≈ ${num(M.parseFunction(r.source)(r.root))}<br>|f(x)| ≈ ${num(r.residual)}</div><p>${r.validation==='sinal'?`Raiz certificada por troca de sinal: f muda de sinal num intervalo de largura ${num(r.bracket[1]-r.bracket[0])} em volta desse x (o tamanho da precisão da máquina). Pelo Teorema do Valor Intermediário existe uma raiz ali. O resíduo ${num(r.effectiveTolerance)} não é alcançável aqui: o arredondamento do ponto flutuante nos termos de f já é maior que isso.`:`Resíduo absoluto exigido: ${num(r.effectiveTolerance)}. A função e os cálculos usam ponto flutuante.`}</p>${certExplain(r)}${intervalExplain(r)}`}<div class="callout ${r.converged?'':'warning'}"><strong>${r.converged?'O critério numérico foi atingido.':'O critério numérico não foi atingido.'}</strong><p>${r.converged?'Isso valida o critério desta execução. Interpretar o domínio, as unidades e o condicionamento continua necessário.':(r.certification?.status==='quase'?'Não trate este ponto como solução. A tolerância absoluta é grande demais para a escala desta função: diminua a tolerância ou procure uma troca de sinal em outra região. Se a curva nunca chega ao eixo, a equação não tem raiz real ali.':'Não trate esta aproximação como solução validada. Ajuste as condições iniciais ou o limite de iterações.')}</p></div>`;}
// O resíduo pequeno sozinho não prova raiz: aqui o aluno vê qual evidência o motor encontrou.
function intervalEcho(I){const sign=I.sign==='troca'?'sinais opostos: há raiz no intervalo (Teorema do Valor Intermediário)':I.sign==='zero'?'uma das pontas já é raiz':'mesmo sinal: a troca de sinal não está garantida';return `<p class="interval-echo"><span class="iv-tag">Intervalo</span> <code>${safe(ivText(I))}</code> <span>f(a) ≈ ${safe(sig5(I.fa))} · f(b) ≈ ${safe(sig5(I.fb))} · ${sign}</span></p>`;}
function intervalExplain(r){const I=r.interval;if(!I)return '';return `<p><strong>Intervalo do exercício:</strong> ${safe(ivText(I))}, com f(a) ≈ ${safe(sig5(I.fa))} e f(b) ≈ ${safe(sig5(I.fb))}. ${I.sign==='troca'?'Como os sinais são opostos e f é contínua ali, o Teorema do Valor Intermediário garante pelo menos uma raiz no intervalo.':I.sign==='zero'?'Uma das pontas já zera f.':'Os sinais são iguais: o intervalo pode não ter raiz, ou ter um número par delas.'} ${I.inside?`A resposta x ≈ ${safe(num(r.root))} está dentro do intervalo.`:`A resposta x ≈ ${safe(num(r.root))} está fora do intervalo: não é a raiz pedida.`}</p>`;}
function certExplain(r){const c=r.certification;if(!c||Array.isArray(r.root))return '';
 if(c.status==='certificada')return `<p><strong>Existência da raiz:</strong> f troca de sinal entre ${num(c.bracket[0])} e ${num(c.bracket[1])}, com valores maiores que o arredondamento. Pelo Teorema do Valor Intermediário há uma raiz nesse intervalo de largura ${num(c.width)}.</p>`;
 if(c.status==='multipla')return `<p><strong>Existência da raiz:</strong> f não troca de sinal perto daqui. O motor procurou o menor |f| e chegou ao nível do arredondamento em x ≈ ${num(c.root)}: é o comportamento de uma raiz de multiplicidade par, como em (x − a)². Sem troca de sinal, a existência não é certificada; trate como raiz provável.</p>`;
 if(c.status==='quase')return `<p><strong>Não é raiz:</strong> |f(x)| ficou abaixo da tolerância, mas o menor valor de |f| perto daqui é ≈ ${num(c.minAbs)} e a curva não cruza nem toca o eixo. Em funções de escala muito pequena, a tolerância absoluta engana: compare |f| com o tamanho dos termos da função.</p>`;
 return '';}
function guideTasks(r){
 if(r.method==='gauss'){
  const tasks=[];
  for(let i=1;i<r.iterations.length;i++){
   const before=r.iterations[i-1].matrix,after=r.iterations[i].matrix,n=after.length;
   const row=after.findIndex((values,j)=>values.some((v,k)=>v!==before[j][k]));
   if(row>=0){const col=after[row][n]!==before[row][n]?n:after[row].findIndex((v,k)=>v!==before[row][k]);tasks.push({value:after[row][col],prompt:`Depois da operação abaixo, qual será o valor da linha ${row+1}, coluna ${col+1}${col===n?' (termo independente)':''}?`,context:r.iterations[i].detail,matrix:before});}
  }
  return tasks;
 }
 const start=r.method==='newton'||r.method==='seidel'||r.method==='fixedpoint'?1:r.method==='secant'?2:0;
 return r.iterations.slice(start).map((row,j)=>{
  const i=start+j,prev=r.iterations[i-1];let context='';
  if(r.method==='bisection')context=`Intervalo [${num(row.a)}; ${num(row.b)}]. Use m=(a+b)/2.`;
  if(r.method==='falseposition')context=`Intervalo [${num(row.a)}; ${num(row.b)}], com f(a) = ${num(row.fa)} e f(b) = ${num(row.fb)}. Use x = (a·f(b) − b·f(a))/(f(b) − f(a)).`;
  if(r.method==='fixedpoint')context=`x anterior = ${num(prev.x)}. Calcule x novo = g(x anterior), com g(x) = ${r.g||'g(x)'}.`;
  if(r.method==='newton')context=`x anterior = ${num(prev.x)}; f(x) = ${num(prev.fx)}; f′(x) ≈ ${num(row.derivative)}. Use x novo = x − f(x)/f′(x).`;
  if(r.method==='secant')context=`x₀=${num(row.x0)}, f(x₀)=${num(row.f0)}; x₁=${num(row.x1)}, f(x₁)=${num(row.f1)}. Use a fórmula da Secante.`;
  if(r.method==='seidel')context=`Vetor anterior: (${prev.x.map(num).join('; ')}). Calcule a primeira incógnita pela primeira equação original, usando os outros valores anteriores. ${r.A[0].map((v,k)=>num(v)+'·'+(r.variables?.[k]||'x'+(k+1))).join(' + ')} = ${num(r.b[0])}.`;
  return {value:Array.isArray(row.x)?row.x[0]:row.x,prompt:r.method==='seidel'?'Qual é a primeira incógnita nesta nova iteração?':'Qual é a próxima aproximação?',context};
 });
}
function guide(r){const tasks=guideTasks(r),t=tasks[s.guideIndex];if(!t)return `<div class="empty-state small">${icon('check')}<h3>${tasks.length?'Etapas guiadas concluídas.':'Não há atualização para praticar.'}</h3><p>${tasks.length?'Você reconstruiu os cálculos desta execução. As atividades guiadas do terminal não geram XP; use as trilhas para registrar sua evolução.':'As condições iniciais já satisfizeram o critério. Experimente outra equação ou outros pontos iniciais.'}</p>${tasks.length?btn('Recomeçar','guide-reset','ghost'):''}</div>`;
 return `<div class="guided-panel"><div class="section-head row tight"><h3>Reconstrua o próximo passo</h3>${tag(`${s.guideIndex+1} / ${tasks.length}`)}</div><p>As respostas completas continuam nas outras abas. Aqui, tente calcular antes de conferir.</p><div class="callout"><p>${safe(t.context)}</p></div>${t.matrix?matrix(t.matrix):''}<form id="guide-form" class="guide-form"><label for="guideAnswer">${t.prompt}</label><input id="guideAnswer" inputmode="decimal" autocomplete="off" value="${safe(s.guideAnswer)}" placeholder="Seu resultado"><div class="row-actions"><button type="submit" class="btn primary" id="guide-check">Conferir passo</button>${s.guideFeedback?.ok?btn('Próximo passo '+icon('arrow'),'guide-next','ghost'):''}</div></form>${s.guideFeedback?`<div class="note ${s.guideFeedback.ok?'ok':'bad'}" role="status">${safe(s.guideFeedback.text)}</div>`:''}<p class="fine">Valores exibidos são arredondados. A conferência aceita arredondamento de aproximadamente 0,0005, com ajuste proporcional para valores grandes.</p></div>`;
}
function checkGuide(){try{const t=guideTasks(s.result)[s.guideIndex];s.guideAnswer=$('#guideAnswer')?.value??s.guideAnswer;const value=parseAnswer(s.guideAnswer),ok=Math.abs(value-t.value)<=Math.max(.00051,Math.abs(t.value)*.00005);s.guideFeedback={ok,text:ok?'Correto. A execução calculou aproximadamente '+num(t.value)+'.':'Ainda não. Refaça a substituição com os valores mostrados e confira os sinais.'};}catch(e){s.guideFeedback={ok:false,text:e.message};}render();}
function collect(){for(const key of ['source','algorithm','a','b','x0','x1','g','min','max','tolerance','maxIterations','initial']){const el=$('#'+key);if(el)s[key]=el.value;}}
function numeric(v){if(String(v).trim()==='')throw Error('Preencha os valores numéricos necessários.');const n=Number(String(v).replace(',','.'));if(!Number.isFinite(n))throw Error('Informe números finitos nas configurações.');return n;}
/* Ponto Fixo: g(x) do campo próprio ou, se vazio, do lado direito de "x = …" (ou do esquerdo de "… = x"). */
function iterationFunction(source,g){
 const clean=t=>String(t).trim().replace(/^g\s*\(\s*x\s*\)\s*=\s*/i,'').replace(/^x\s*=\s*/,'');
 if(String(g||'').trim()){const c=clean(g);if(c.includes('='))throw Error('Em g(x), escreva só a expressão, como cos(x) ou (x + 2)^(1/3).');return c;}
 const parts=String(source).split('=');
 if(parts.length===2&&/^\s*x\s*$/.test(parts[0]))return parts[1].trim();
 if(parts.length===2&&/^\s*x\s*$/.test(parts[1]))return parts[0].trim();
 throw Error('O Ponto Fixo precisa de uma função de iteração g(x). Escreva a equação na forma x = g(x), como x = cos(x), ou preencha o campo "Ponto Fixo: g(x)" nos controles.');
}
function solve(){collect();let source=s.source.trim();s.error='';s.errorFix=null;s.result=null;
 if(source.startsWith('/')){if(source==='/help')s.help=true;else if(source==='/history')s.historyOpen=true;else if(source==='/clear'){s.source='';s.help=false;s.historyOpen=false;}else s.error='Comando desconhecido. Use /help, /history ou /clear.';render();return;}
 try{if(!source||source.length>4000)throw Error('Digite uma expressão de até 500 caracteres ou um sistema de até 4.000 caracteres.');const options={tolerance:numeric(s.tolerance),maxIterations:numeric(s.maxIterations)};
 const system=source.includes('\n')||source.includes('|');let r;if(system){s.mode='system';const {A,b,variables}=M.parseSystem(source),initial=s.initial.trim()?s.initial.trim().split(/[;,\s]+/).map(Number):A.map(()=>0);if(initial.length!==A.length||initial.some(v=>!Number.isFinite(v)))throw Error('Vetor inicial: informe um número por incógnita, separados por espaço ou vírgula.');const alg=['gauss','seidel'].includes(s.algorithm)?s.algorithm:'auto';s.algorithm=alg;r=alg==='gauss'?M.gauss(A,b,options):alg==='seidel'?M.seidel(A,b,initial,options):M.autoSystem(A,b,initial,options);Object.assign(r,{A,b,variables});}
 else{s.mode='root';if(['gauss','seidel'].includes(s.algorithm))s.algorithm='auto';const out=solveRoot(source,options);r=out.r;source=out.source;}
 s.result={...r,source,effectiveTolerance:!system&&s.algorithm==='auto'?1e-12:options.tolerance};s.resultTab='solution';s.guideIndex=0;s.guideAnswer='';s.guideFeedback=null;if(r.converged){p.labCount++;const summary=Array.isArray(r.root)?r.root.map(num).join('; '):'x ≈ '+num(r.root)+(r.certification?.status==='multipla'?' (raiz provável, sem troca de sinal)':'');const hsrc=r.interval?`${source} em [${String(s.a).trim()}; ${String(s.b).trim()}]`:source;p.history=[{source:hsrc,summary,method:r.method,date:new Date().toLocaleDateString('pt-BR')},...p.history.filter(h=>h.source!==hsrc)].slice(0,10);persist();}
 }catch(e){s.error=e.message;}render();}
function parseAnswer(raw){const text=String(raw).trim().replace(',','.');if(!text)throw Error('Escreva um número ou uma fração antes de conferir.');if(!/^\s*[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:e[+-]?\d+)?(?:\s*\/\s*[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:e[+-]?\d+)?)?\s*$/i.test(text))throw Error('Use um número decimal ou uma fração, como 1,416667 ou 17/12.');const a=text.split('/').map(Number),n=a.length===2?a[0]/a[1]:a[0];if(!Number.isFinite(n))throw Error('Esse número não é finito. Confira a divisão.');return n;}
// Recompensas (v11): moedas por atividade nova, bônus a cada 3 acertos seguidos e bônus de fase e de mundo, pagos uma vez só.
function reward(id,earned){let coins=0,kind='ok';const notes=[];
 if(earned.first){coins+=id.startsWith('p:')?5:2;s.streakNew=true;}
 s.streak=(s.streak||0)+1;if(s.streak>(p.best||0))p.best=s.streak;
 if(s.streak%3===0){kind='combo';if(s.streakNew){coins+=5;s.streakNew=false;notes.push(`${s.streak} acertos seguidos: +5 moedas`);}else notes.push(`${s.streak} acertos seguidos`);}
 const m=/^c:([a-z]+):(\d+)$/.exec(id);
 if(m){const mid=m[1],lv=Math.floor(+m[2]/4),key=`n:${mid}:${lv}`;
  if(!p.paid[key]&&levelDone(mid,lv)){p.paid[key]=true;coins+=10;kind='level';notes.push(`Nível ${lv+1} de ${method(mid).title} concluído: +10 moedas`);const nx=nextWorld(mid);if(lv===0&&nx&&!p.free)notes.push(`Mundo ${worldIdx(nx.id)+1}, ${nx.title}, liberado`);}
  if(!p.paid['w:'+mid]&&doneCount(mid)===12){p.paid['w:'+mid]=true;coins+=30;kind='world';notes.push(`Mundo ${method(mid).title} completo: +30 moedas`);}}
 p.coins=(p.coins||0)+coins;return {coins,kind,notes};}
function answerQuestion(){const id=currentId();if(!id)return;const t=taskFor(id);try{let ok;if(t.type==='choice'){if(s.selected===null)throw Error('Selecione uma alternativa antes de conferir.');ok=s.selected===t.answer;}else{s.answer=$('#answer')?.value??s.answer;const n=parseAnswer(s.answer);ok=Math.abs(n-t.value)<=Math.max(.00051,Math.abs(t.value)*.00005);}
 if(ok){const earned=P.complete(p,id,{wrong:s.wrong,hint:s.hint,review:s.page==='review'});const rw=reward(id,earned);s.feedback={ok:true,message:`Correto. ${t.explain} ${earned.xp?`+${earned.xp} XP`:'Questão revisada'}${rw.coins?` · +${rw.coins} ${rw.coins===1?'moeda':'moedas'}`:''}. ${'★'.repeat(earned.stars)}${'☆'.repeat(3-earned.stars)}${rw.notes.length?' '+rw.notes.join('. ')+'.':''}`};s.mascot={kind:rw.kind,coins:rw.coins};if(rw.notes.length)announce(rw.notes.join('. '));}
 else{s.wrong++;P.wrong(p,id);s.streak=0;s.streakNew=false;s.mascot={kind:'bad'};s.feedback={ok:false,message:t.wrong||'Separe os dados, confira a fórmula e recalcule os sinais. Você pode pedir uma dica; a resposta completa aparece depois do acerto.'};}persist();render();}catch(e){s.feedback={ok:false,message:e.message};render();}}
function download(name,content,type='text/plain'){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function exportResult(csv=false){const r=s.result;if(!r)return;if(csv){const rows=[['k','x','f(x) ou residuo','variacao','operacao'],...r.iterations.map(t=>[t.i,Array.isArray(t.x)?t.x.join(' ; '):t.x,t.residual??t.fx,t.error,t.detail])];download('numera-iteracoes.csv','﻿'+rows.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\n'),'text/csv;charset=utf-8');return;}const report=['NUMERA ACADEMY — RESOLUÇÃO NUMÉRICA',new Date().toLocaleString('pt-BR'),'','ENTRADA',r.source,...(r.interval?['INTERVALO: '+ivText(r.interval)]:[]),'','MÉTODO: '+method(r.method).title,'SOLUÇÃO: '+(Array.isArray(r.root)?r.root.join('; '):r.root),'RESÍDUO: '+r.residual,'CRITÉRIO: '+(r.converged?'atingido':'não atingido'),'TOLERÂNCIA: '+r.effectiveTolerance,'',r.recommendation||'Método manual.',r.note||'','PASSO A PASSO',...r.iterations.map(t=>`${t.i}. ${t.detail}\n${t.matrix?t.matrix.map(row=>row.join(' | ')).join('\n'):'x = '+JSON.stringify(t.x)+'; resíduo/f = '+(t.residual??t.fx)+'; variação = '+t.error}`),'','COMPARAÇÃO',JSON.stringify(r.comparisons||[],null,2),'','LIMITES','Resíduo pequeno não garante erro pequeno. Busca automática limitada e sem garantia de todas as raízes. Newton usa derivada numérica. Sistemas utilizam resíduo normalizado.'];const pretty=window.NumeraCalc?window.NumeraCalc.toPretty:(v=>v);download('numera-resolucao.txt',pretty(report.join('\n')));}

/* ---------- Renderização e eventos ---------- */
const TITLES={treino:'Treino',home:'Início',academy:'Trilhas',cases:'Missões',case:'Missão',jogos:'Jogos',lab:'Terminal',review:'Revisão',progress:'Progresso'};
function focusMode(){return s.page==='course'&&s.tab!=='learn'||s.page==='case'||s.page==='review'&&s.reviewId&&P.ids.has(s.reviewId);}
// Depois de redesenhar, o foco volta ao "mesmo" controle (mesmo id ou mesma ação), ou ao alvo pedido pela tela.
function focusKey(el){if(!el||!el.getAttribute)return null;if(el.id&&el.id!=='main')return '#'+el.id;const act=el.getAttribute('data-act');if(!act)return null;let sel=`[data-act="${act}"]`;for(const k of ['data-id','data-index','data-page'])if(el.getAttribute(k)!==null)sel+=`[${k}="${String(el.getAttribute(k)).replace(/"/g,'')}"]`;return sel;}
function restoreFocus(key){try{const want=focusAfter||key;focusAfter=null;if(!want)return;const el=document.querySelector(want);if(el&&el.focus)el.focus({preventScroll:!!key&&want===key});}catch(_){}}
// Expoentes de verdade em todo texto da página (v10.1): x^3 → x³ (em <sup>), e^(−x) → e com −x elevado, 10^-6 → 10⁻⁶.
// Só mexe no texto entre as tags: atributos, a <textarea> da equação (o teclado cuida dela) e os desenhos SVG ficam como estão.
// "Use x, ^, parênteses" continua com o ^, porque ali não há base nem expoente: é o nome da tecla.
function supText(t){let out='',i=0;
 while(i<t.length){
  if(t[i]==='^'&&i>0&&/[\w)\]}²³π.]/.test(t[i-1])){const j=i+1;
   if(t[j]==='('||t[j]==='{'){const open=t[j],close=open==='('?')':'}';let d=0,k=j;for(;k<t.length;k++){if(t[k]===open)d++;else if(t[k]===close&&--d===0)break;}
    if(k<t.length){out+='<sup>'+supText(t.slice(j+1,k)).replace(/-/g,'−')+'</sup>';i=k+1;continue;}}
   const m=/^[+\-−]?(?:\d+(?:[.,]\d+)?|[a-zA-Zπ])/.exec(t.slice(j));
   if(m){out+='<sup>'+m[0].replace('-','−')+'</sup>';i=j+m[0].length;continue;}}
  out+=t[i];i++;}
 return out;}
function supHtml(html){if(html.indexOf('^')<0)return html;let skip=0;
 return html.split(/(<[^>]*>)/).map(part=>{if(part.charAt(0)==='<'){const m=/^<(\/?)(textarea|svg)\b/i.exec(part);if(m&&!/\/>$/.test(part))skip=Math.max(0,skip+(m[1]?-1:1));return part;}
  return skip>0||part.indexOf('^')<0?part:supText(part);}).join('');}
function render(){const pages={home,academy,course,cases,case:casePage,jogos,lab,progress,review,treino:()=>TR?TR.page():''};let fkey=null;try{fkey=focusKey(document.activeElement);}catch(_){}if(!pages[s.page])s.page='home';document.title='Numera Academy · '+(s.page==='course'?method(s.method).title:TITLES[s.page]);const focus=focusMode();const notice=s.warning?`<div class="wrap"><div class="notice" role="status"><span>${safe(s.warning)}</span>${btn('Fechar','dismiss','text')}</div></div>`:'';
 $('#app').innerHTML=supHtml(focus?`<div class="app-shell focus"><main id="main" tabindex="-1" class="page-${s.page==='case'?'case-page':s.page}">${notice}${pages[s.page]()}</main></div>`:`<div class="app-shell">${topbar()}<main id="main" tabindex="-1" class="page-${s.page}">${notice}${pages[s.page]()}</main>${footer()}${mobileNav()}</div>`);
 restoreFocus(fkey);
 if(s.page==='home')startAuto();else stopAuto();
 mascots();}
// O casal aparece só onde há desafio: prática da trilha, missão e revisão ativa.
const mascotOn=()=>(s.page==='course'&&s.tab==='practice')||s.page==='case'||(s.page==='review'&&!!s.reviewId&&P.ids.has(s.reviewId));
function mascots(){const MZ=window.NumeraMascotes;if(!MZ)return;try{MZ.update({visible:mascotOn(),outfit:p.outfit||[]});if(s.mascot){const r=s.mascot;s.mascot=null;MZ.react(r.kind,{coins:r.coins});}}catch(_){}}
function openCourse(id){s.method=id;s.q=nextQ(id);s.tab='learn';s.sim=0;s.introStep=0;s.pathSel=null;navigate('course');}
function startNode(key){if(key!=='intro'&&key!=='sim'&&!worldOpen(s.method)){s.pathSel=key;render();return;}if(key==='intro'){s.tab='intro';s.introStep=0;}else if(key==='sim'){s.tab='simulate';s.sim=0;}else{const i=Number(key.slice(1));if(i>nextQ(s.method)&&!p.completed[`c:${s.method}:${i}`])return;s.q=i;s.tab='practice';}resetQuestion();s.pathSel=null;render();window.scrollTo({top:0,behavior:'auto'});}
const raf=window.requestAnimationFrame?window.requestAnimationFrame.bind(window):(fn=>setTimeout(fn,16));let dragging=false,queued=false;
function demoFromPointer(e){const svg=$('.demo-svg.draggable');if(!svg)return;const box=svg.getBoundingClientRect();if(!box.width)return;const vx=(e.clientX-box.left)/box.width*G.W,x=G.lo+(vx-G.L)/(G.W-G.L-G.R)*(G.hi-G.lo);setNewtonX(x);s.demos.newton.k=0;if(!queued){queued=true;raf(()=>{queued=false;refreshDemo();});}}
document.addEventListener('pointerdown',e=>{if(e.target.closest&&e.target.closest('#hero-widget'))stopAuto();if(e.target.closest&&e.target.closest('.demo-svg.draggable')){dragging=true;e.preventDefault();demoFromPointer(e);}});
document.addEventListener('pointermove',e=>{if(dragging)demoFromPointer(e);});
